.SequencerThumb {
  width: 56px;
  height: 56px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  object-fit: cover;
  background: rgba(0, 0, 0, 0.25);
}

.SequencerBadge {
  font-size: 10px;
  letter-spacing: 0.08em;
  padding: 4px 6px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  white-space: nowrap;
  opacity: 0.9;
  flex-shrink: 0;
}

.SequencerBadgePreset {
  border-color: rgba(0, 255, 255, 0.45);
  color: rgba(0, 255, 255, 0.9);
}

.SequencerBadgeComposite {
  border-color: rgba(255, 119, 255, 0.5);
  color: rgba(255, 119, 255, 0.95);
}

.SequencerBadgeSeq {
  border-color: rgba(255, 200, 0, 0.55);
  color: rgba(255, 200, 0, 0.95);
}

.SequencerBadgeLayer {
  border-color: rgba(160, 120, 255, 0.55);
  color: rgba(160, 120, 255, 0.95);
}

.SequencerBadgeEffect {
  border-color: rgba(0, 255, 255, 0.45);
  color: rgba(0, 255, 255, 0.9);
}

.SequencerItem {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  user-select: none;
}

.SequencerItemSeq {
  display: grid;
  grid-template-columns: 56px 1fr;
  grid-template-rows: auto auto;
  column-gap: 10px;
  row-gap: 6px;
  align-items: center;
}

.SequencerSeqThumb {
  grid-column: 1;
  grid-row: 1 / span 2;
}

.SequencerSeqHeader {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.SequencerSeqName {
  min-width: 0;
  flex: 1;
  font-size: 13px;
  line-height: 1.2;
  overflow-x: auto;
  overflow-y: hidden;
  text-overflow: clip;
  white-space: nowrap;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.SequencerSeqName::-webkit-scrollbar {
  height: 0;
}

.SequencerSeqActions {
  grid-column: 2;
  grid-row: 2;
  display: flex;
  gap: 8px;
  align-items: center;
}

.SequencerSeqActionsSpacer {
  flex: 1;
}

.SequencerSeqIconButton {
  width: 34px;
  height: 30px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.SequencerItem:hover {
  border-color: rgba(0, 255, 255, 0.35);
}

.SequencerItem[draggable="true"] {
  cursor: grab;
}

.SequencerItem[draggable="true"]:active {
  cursor: grabbing;
}

.SequencerItemName {
  font-size: 13px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.SequencerItemMeta {
  font-size: 11px;
  opacity: 0.7;
}

.SequencerContent {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.SequencerTopBar {
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.SequencerTopBarActions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}

.SequencerTopBar button {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #e8eefc;
  border-radius: 7px;
  padding: 8px 10px;
  cursor: pointer;
}

.SequencerTopBar button:hover {
  border-color: rgba(0, 255, 255, 0.35);
}

.SequencerIconButton {
  width: 36px;
  height: 36px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  line-height: 1;
}

.SequencerIconButton.isOn {
  border-color: rgba(0, 255, 255, 0.55);
  background: rgba(0, 255, 255, 0.14);
}

.SequencerTransportButton {
  min-width: 74px;
  height: 34px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 8px;
  background: #111;
  border-color: rgba(255, 255, 255, 0.18);
  font-size: 12px;
  letter-spacing: 0.06em;
}

.SequencerTransportButtonIcon {
  font-size: 13px;
  line-height: 1;
}

.SequencerTransportButtonLabel {
  line-height: 1;
}

.SequencerOutputMapButton {
  height: 36px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  letter-spacing: 0.08em;
  line-height: 1;
}

.SequencerTagToggleButton {
  min-width: 92px;
  justify-content: center;
}

.SequencerOutputMapButton.isOn {
  border-color: rgba(0, 255, 255, 0.55);
  background: rgba(0, 255, 255, 0.14);
}

.SequencerOutputMapEye {
  font-size: 14px;
}

.SequencerOutputMapEye.isOff {
  opacity: 0.35;
}

.SequencerTopBarMeta {
  opacity: 0.85;
  font-size: 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.SequencerTopBarMetaCurrent {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-variant-numeric: tabular-nums;
}

.SequencerDurationInput {
  width: 140px;
  height: 30px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e8eefc;
  border-radius: 7px;
  padding: 0 10px;
  outline: none;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-variant-numeric: tabular-nums;
}

.SequencerDurationInput:focus {
  border-color: rgba(0, 255, 255, 0.45);
  box-shadow: 0 0 0 2px rgba(0, 255, 255, 0.12);
}

.SequencerTopBarMetaStatus {
  margin-left: 10px;
  opacity: 0.75;
}

.SequencerTransportBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.SequencerTransportBarLeft {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.SequencerTransportBarMeta {
  margin-left: 8px;
}

.SequencerCloseModalOverlay {
  position: fixed;
  inset: 0;
  z-index: 1000000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(3, 8, 18, 0.72);
  backdrop-filter: blur(6px);
}

.SequencerCloseModal {
  width: min(460px, calc(100vw - 32px));
  border-radius: 14px;
  border: 1px solid rgba(0, 255, 255, 0.24);
  background:
    linear-gradient(180deg, rgba(14, 21, 34, 0.98), rgba(7, 12, 22, 0.98));
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.48);
  overflow: hidden;
}

.SequencerCloseModalHeader {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.SequencerCloseModalTitle {
  color: #e8eefc;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.SequencerCloseModalBody {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.SequencerCloseModalMessage {
  font-size: 15px;
  color: rgba(232, 238, 252, 0.96);
}

.SequencerCloseModalDetail {
  font-size: 13px;
  line-height: 1.5;
  color: rgba(232, 238, 252, 0.76);
}

.SequencerCloseModalActions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 0 18px 18px;
}

.SequencerPreview {
  flex: 1;
  min-height: 0;
  position: relative;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: #000;
  transition: filter 0.25s ease, opacity 0.25s ease;
}

.SequencerStatsOverlay {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 6;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
}

.SequencerStatsToggle {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid rgba(0, 255, 255, 0.32);
  background: rgba(5, 12, 20, 0.76);
  color: #8ffcff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  pointer-events: auto;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(8px);
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.SequencerStatsToggle:hover {
  background: rgba(8, 18, 28, 0.92);
  border-color: rgba(0, 255, 255, 0.55);
  transform: translateY(-1px);
}

.SequencerStatsToggle.isActive {
  background: rgba(0, 255, 255, 0.12);
  border-color: rgba(0, 255, 255, 0.72);
}

.SequencerStatsIconSvg {
  width: 16px;
  height: 16px;
}

.SequencerStatsPanel {
  width: 220px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(0, 255, 255, 0.22);
  background: rgba(2, 8, 14, 0.74);
  color: rgba(228, 249, 255, 0.96);
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 12px;
  line-height: 1.35;
  pointer-events: auto;
  backdrop-filter: blur(10px);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.32);
}

.SequencerStatsTitleRow,
.SequencerStatsMetricRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.SequencerStatsTitleRow {
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.SequencerStatsMetricRow + .SequencerStatsMetricRow {
  margin-top: 6px;
}

.SequencerStatsTitle {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #8ffcff;
}

.SequencerStatsSource,
.SequencerStatsLabel {
  color: rgba(188, 220, 228, 0.82);
}

.SequencerStatsSource {
  font-size: 10px;
  text-transform: uppercase;
}

.SequencerStatsValue {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: #ffffff;
}

.SequencerTimelineResizeHandle {
  height: 14px;
  flex: 0 0 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: row-resize;
  background: #000;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  user-select: none;
}

.SequencerTimelineResizeHandle:hover,
.SequencerTimelineResizeHandle.isDragging {
  background: rgba(255, 255, 255, 0.03);
}

.SequencerTimelineResizeGrip {
  width: 120px;
  max-width: calc(100% - 24px);
  height: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  box-shadow: 0 0 0 1px rgba(0, 255, 255, 0.06);
}

.SequencerTimelineResizeHandle:hover .SequencerTimelineResizeGrip,
.SequencerTimelineResizeHandle.isDragging .SequencerTimelineResizeGrip {
  background: rgba(0, 255, 255, 0.65);
}

.SequencerTimeline {
  height: 280px;
  min-height: 220px;
  background: #000;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overscroll-behavior-x: contain;
  transition: height 0.26s ease;
}

.SequencerTimeline.isDraggingResize {
  transition: none;
}

.SequencerTimeBar {
  height: 48px;
  display: flex;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: #000;
}

.SequencerTimeBarLeft {
  width: 220px;
  min-width: 220px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  background: #000;
  display: flex;
  align-items: center;
  padding: 0 10px;
  box-sizing: border-box;
}

.SequencerTimeBarRight {
  flex: 1;
  min-width: 0;
  padding: 4px 0;
  background: #000;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.SequencerZoomLayer {
  position: relative;
  z-index: 20;
  width: 100%;
  height: 12px;
  background: #1a1a1a;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.75);
  overflow: hidden;
}

.SequencerTimeBarTrack {
  width: 100%;
  height: 24px;
  border-radius: 6px;
  background: #1a1a1a;
  border: 1px solid rgba(255, 255, 255, 0.18);
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.75);
  z-index: 10;
}

.SequencerTimelineScrollbarWindow {
  position: absolute;
  top: 1px;
  bottom: 1px;
  min-width: 0;
  background: #002424;
  opacity: 1;
  border-radius: 9px;
  cursor: grab;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.7);
  z-index: 4;
}

.SequencerTimelineScrollbarWindow:hover {
  background: #597d7d;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.75), 0 0 0 2px rgba(255, 255, 255, 0.12);
}

.SequencerTimelineScrollbarWindow:active {
  background: #809292;
  cursor: grabbing;
}

.SequencerTimelineScrollbarHandle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  background: #001616;
  cursor: ew-resize;
  z-index: 5;
}

.SequencerTimelineScrollbarHandle:hover {
  background: #597d7d;
}

.SequencerTimelineScrollbarHandleStart {
  left: 0;
  border-right: 1px solid rgba(0, 0, 0, 0.5);
}

.SequencerTimelineScrollbarHandleEnd {
  right: 0;
  border-left: 1px solid rgba(0, 0, 0, 0.5);
}

.SequencerTimeBarViewport {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.SequencerTimeBarContent {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
}

.SequencerTimeBarPlayhead {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: rgba(255, 0, 128, 0.9);
  pointer-events: none;
  z-index: 6;
}

.SequencerZoomControls {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.SequencerZoomSlider {
  width: 160px;
  height: 36px;
  accent-color: rgba(0, 255, 255, 0.85);
}

.SequencerTracksShell {
  flex: 1;
  min-height: 0;
  display: flex;
  background: #000;
  overflow: hidden;
}

.SequencerTracksLabels {
  width: 220px;
  min-width: 220px;
  background: #000;
  position: relative;
  overflow: hidden;
  flex: 0 0 auto;
}

.SequencerTracksLabelsInner {
  will-change: transform;
}

.SequencerTracksLabels .SequencerTrackLabel {
  position: relative;
  left: auto;
  z-index: auto;
}

.SequencerTracksLabels .SequencerTagRow {
  position: relative;
  top: auto;
  z-index: 1;
}

.SequencerTracksScroll {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  overflow-y: auto;
  position: relative;
  background: #000;
  scrollbar-width: none;
  -ms-overflow-style: none;
  overscroll-behavior-x: contain;
}

.SequencerTracksScroll::-webkit-scrollbar {
  width: 0;
  height: 0;
}

.SequencerTrackRow {
  display: flex;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  min-height: 80px;
}

.SequencerTrackRow:not(.SequencerTagRow) {
  height: 80px;
}

.SequencerTrackRow.isCollapsed {
  min-height: 44px;
}

.SequencerTrackRow.isCollapsed:not(.SequencerTagRow) {
  height: 44px;
}

.SequencerTrackRow.isCollapsed .SequencerTrackLabel {
  padding: 6px 8px;
  gap: 6px;
}

.SequencerTrackRow.isCollapsed .SequencerTrackLabel input {
  height: 24px;
}

.SequencerTrackRow.isCollapsed .SequencerTrackLane .SequencerClip {
  top: 6px;
  bottom: 6px;
  height: auto;
  padding: 4px 8px;
  border-radius: 7px;
  font-size: 11px;
  gap: 8px;
}

.SequencerTrackRow.isCollapsed .SequencerTrackLane .SequencerClipKeyframes {
  top: 4px;
  bottom: 4px;
}

.SequencerTrackRow.isInactive .SequencerTrackLane {
  opacity: 0.28;
  filter: grayscale(0.85);
  transition: opacity 0.2s ease, filter 0.2s ease;
}

.SequencerTrackRow.isInactive .SequencerTrackName input {
  opacity: 0.55;
  filter: grayscale(0.85);
}

.SequencerTrackRow.isInactive .SequencerTrackControls .SequencerSmallButton {
  opacity: 1;
  filter: none;
}

.SequencerTagRow {
  min-height: 44px;
  height: 44px;
  position: sticky;
  top: 0;
  z-index: 950;
  background: #000;
}

.SequencerTagRow .SequencerTrackLabel {
  min-height: 44px;
  height: 44px;
}

.SequencerTagRow .SequencerTrackLane {
  height: 44px;
}

.SequencerTagRow .SequencerTrackControls {
  justify-content: flex-start;
  gap: 6px;
}

.SequencerRulerTick {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 0;
  pointer-events: none;
  z-index: 5;
}

.SequencerRulerTick.isMinor .SequencerRulerLine {
  opacity: 0.55;
}

.SequencerRulerTick.isMajor .SequencerRulerLine {
  opacity: 1;
}

.SequencerRulerLine {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 1px;
  background: rgba(255, 255, 255, 0.25);
}

.SequencerRulerText {
  position: absolute;
  top: 6px;
  left: 6px;
  font-size: 11px;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.9);
  white-space: nowrap;
  pointer-events: none;
}

.SequencerTagLabel {
  font-size: 12px;
  letter-spacing: 0.12em;
  opacity: 0.9;
}

.SequencerTrackLabel {
  width: 220px;
  min-width: 220px;
  padding: 8px 10px;
  border-right: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  align-items: center;
  gap: 8px;
  position: sticky;
  left: 0;
  z-index: 1000;
  background: #000;
  overflow: hidden;
  box-sizing: border-box;
}

.SequencerTrackRow:not(.SequencerTagRow) .SequencerTrackLabel {
  height: 100%;
}

.SequencerTrackRow:not(.SequencerTagRow):not(.isCollapsed) .SequencerTrackLabel {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 7px;
}

.SequencerTrackRow.isCollapsed:not(.SequencerTagRow) .SequencerTrackLabel {
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
}

.SequencerTrackRow.isCollapsed:not(.SequencerTagRow) .SequencerTrackControls {
  margin-left: auto;
}

.SequencerTrackRow:not(.SequencerTagRow):not(.isCollapsed) .SequencerTrackControls {
  width: 100%;
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: 4px;
}

.SequencerTrackRow:not(.SequencerTagRow) .SequencerTrackControls .SequencerSmallButton {
  width: 24px;
  height: 24px;
  padding: 0;
  font-size: 12px;
}

.SequencerTrackRow:not(.SequencerTagRow) .SequencerTrackLabel input {
  height: 28px;
}

.SequencerTrackLabelSelected {
  border-right-color: rgba(0, 255, 255, 0.35);
  box-shadow: inset 3px 0 0 rgba(0, 255, 255, 0.8);
}

.SequencerTrackName {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.SequencerTrackNameText {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  opacity: 0.95;
}

.SequencerCollapseButton {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(0, 255, 255, 0.95);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  line-height: 1;
  font-size: 14px;
}

.SequencerCollapseButton:hover {
  border-color: rgba(0, 255, 255, 0.5);
  background: rgba(0, 255, 255, 0.12);
}

.SequencerTrackControls {
  flex: 0 0 auto;
  display: flex;
  gap: 6px;
  align-items: center;
}

.SequencerTrackLabel input {
  flex: 1;
  min-width: 0;
  background: #111;
  border: 1px solid rgba(255, 255, 255, 0.18);
  color: #e8eefc;
  border-radius: 6px;
  padding: 6px 8px;
  outline: none;
  font-size: 12px;
}

.SequencerTrackLane {
  flex: 0 0 auto;
  position: relative;
  z-index: 0;
  overflow: hidden;
  height: 100%;
}

.SequencerTagLane {
  background: #000;
}

.SequencerTagSegment {
  position: absolute;
  top: calc(50% - 14px);
  height: 28px;
  min-width: 90px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  box-sizing: border-box;
  border-radius: 6px;
  border: 1px solid rgba(255, 200, 0, 0.55);
  background: rgba(255, 200, 0, 0.14);
  color: rgba(255, 235, 190, 0.95);
  font-size: 12px;
  cursor: grab;
  user-select: none;
  overflow: hidden;
  z-index: 1;
}

.SequencerTagSegment:active {
  cursor: grabbing;
}

