export const SequencerApp: React.FC = () => {
  const t = (key: string, fallback?: string) => i18n.t(key, fallback);

  // New state for display selector
  const [showDisplaySelector, setShowDisplaySelector] = useState(false);
  const [availableDisplays, setAvailableDisplays] = useState<any[]>([]);
  const [showCloseConfirmModal, setShowCloseConfirmModal] = useState(false);
  const [isCloseConfirmSaving, setIsCloseConfirmSaving] = useState(false);
  const [librarySectionsOpen, setLibrarySectionsOpen] = useState({
    sequences: true,
    effects: false,
    presets: false,
    layers: false
  });

  const handleLaunch2D = async () => {
    if (!(window as any).volumetricElectron?.openOutputFullscreen) {
      const sessionId = getSocketSessionId();
      const url = CONFIG.getPageUrl('output.html', {
        session: sessionId && sessionId !== '0' ? sessionId : undefined,
        hideMenu: 'true',
        showheader: 'false'
      });
      window.open(url, '_blank', 'noopener,noreferrer');
      return;
    }

    try {
      const displays = await (window as any).volumetricElectron.getDisplays();
      if (!displays || displays.length === 0) {
        // Fallback if no displays detected
        (window as any).volumetricElectron.openOutputFullscreen(null);
      } else if (displays.length === 1) {
        // Just launch on the only monitor
        (window as any).volumetricElectron.openOutputFullscreen(displays[0].id);
      } else {
        // Show selection prompt
        setAvailableDisplays(displays);
        setShowDisplaySelector(true);
      }
    } catch (err) {
      console.error("Failed to get displays", err);
      (window as any).volumetricElectron.openOutputFullscreen(null);
    }
  };

  const toggleLibrarySection = useCallback((section: keyof typeof librarySectionsOpen) => {
    setLibrarySectionsOpen(prev => ({ ...prev, [section]: !prev[section] }));
  }, []);

  const { broadcastUpdate, remoteState, isUpdatingFromRemote, isMasterClient, socket } = useSocketSync(true, 'sequencer');
  const isUpdatingFromPropsRef = useRef(false);
  const sequenceRef = useRef<TimelineSequence>(buildDefaultSequence());
  const isPlayingRef = useRef(false);

  const [allPresets, setAllPresets] = useState<AnyPreset[]>([]);
  const [bufferStats, setBufferStats] = useState<{ count: number; details: Array<{ layerId: string; shaderId: string; presetName: string }> }>({ count: 0, details: [] });
  const [savedLayers, setSavedLayers] = useState<SavedLayer[]>([]);
  const [sequence, setSequence] = useState<TimelineSequence>(() => buildDefaultSequence());
  const [loadedSequencePresetId, setLoadedSequencePresetId] = useState<string | null>(null);
  const [importedSequenceName, setImportedSequenceName] = useState<string | null>(null);

  const [librarySearch, setLibrarySearch] = useState<LibrarySearchState>(DEFAULT_LIBRARY_SEARCH);

  // Auto-expand sections when filter kind changes
  useEffect(() => {
    const kind = librarySearch.kind;
    setLibrarySectionsOpen(prev => {
      const next: typeof prev = { ...prev };
      if (kind === 'all') {
        next.sequences = true;
        next.effects = true;
        next.presets = true;
        next.layers = true;
      } else {
        next.sequences = kind === 'sequence';
        next.effects = kind === 'effect';
        next.presets = kind === 'preset' || kind === 'composite';
        next.layers = kind === 'layer';
      }
      // Only update if something changed
      if (next.sequences === prev.sequences && next.effects === prev.effects && 
          next.presets === prev.presets && next.layers === prev.layers) return prev;
      return next;
    });
  }, [librarySearch.kind]);

  const [paramVersion, setParamVersion] = useState(0);
  const [confirmUpdateSequence, setConfirmUpdateSequence] = useState(false);
  const [selectedTrackId, setSelectedTrackId] = useState<string>('t1');
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [selectedTagId, setSelectedTagId] = useState<string | null>(null);
