          const frames = (nextKeyframes[paramKey] || []).slice().sort((a, b) => a.tMs - b.tMs);
          const idx = frames.findIndex(f => Math.abs(f.tMs - localT) <= 6);
          if (idx >= 0) frames[idx] = { tMs: localT, value };
          else frames.push({ tMs: localT, value });
          frames.sort((a, b) => a.tMs - b.tMs);
          nextKeyframes[paramKey] = frames;
