  const moveKeyframeForSelectedClip = useCallback((paramKey: string, fromTMs: number, toTMs: number, valueRaw: any) => {
    if (!selected) return;
    const { track, clip } = selected;
    const valueNum = typeof valueRaw === 'number' ? valueRaw : Number(valueRaw);
    const value = typeof valueRaw === 'boolean'
      ? valueRaw
      : (isFinite(valueNum) && String(valueRaw).trim() !== '' ? valueNum : valueRaw);
    setSequence(prev => {
