          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) } as Record<string, Array<{ tMs: number; value: any }>>;
          const frames = (nextKeyframes[paramKey] || []).slice().sort((a, b) => a.tMs - b.tMs);
          const withoutFrom = frames.filter(f => Math.abs(f.tMs - fromTMs) > 6);
          const withoutCollision = withoutFrom.filter(f => Math.abs(f.tMs - toTMs) > 6);
          withoutCollision.push({ tMs: toTMs, value });
          withoutCollision.sort((a, b) => a.tMs - b.tMs);
          nextKeyframes[paramKey] = withoutCollision;
