  const resolveKeyframeValue = useCallback((paramKey: string) => {
    if (!selectedPresetForPanel) return undefined;

    if (paramKey.startsWith('global_')) {
      const id = paramKey.slice('global_'.length);
      const def = globalParamDefs.find(p => p.id === id);
      const gs = (selectedPresetForPanel as any).globalSettings || {};
      const colors = (selectedPresetForPanel as any).colors || {};
      const v = id === 'raymarchColor1'
        ? (colors.color1 ?? gs.raymarchColor1 ?? def?.defaultValue)
        : id === 'raymarchColor2'
          ? (colors.color2 ?? gs.raymarchColor2 ?? def?.defaultValue)
          : (gs[id] ?? def?.defaultValue);
      const num = typeof v === 'number' ? v : Number(v);
      return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
    }

    if (paramKey.startsWith('compositeG_')) {
      const match = paramKey.match(/^compositeG_(\d+)_(.+)$/);
      if (!match) return undefined;
      const layerIndex = Number(match[1]);
      const id = match[2];
      const def = globalParamDefs.find(p => p.id === id);
      const composite = selectedPresetForPanel as any;
      const layer = composite.layers?.[layerIndex];
      const gs = layer?.globalSettings || {};
      const colors = layer?.colors || {};
      const v = id === 'raymarchColor1'
        ? (colors.color1 ?? gs.raymarchColor1 ?? def?.defaultValue)
        : id === 'raymarchColor2'
          ? (colors.color2 ?? gs.raymarchColor2 ?? def?.defaultValue)
          : (gs[id] ?? def?.defaultValue);
      const num = typeof v === 'number' ? v : Number(v);
      return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
    }

    if (isCompositePreset(selectedPresetForPanel as any) && /^composite_\d+_/.test(paramKey)) {
      const match = paramKey.match(/^composite_(\d+)_(.+)$/);
      if (!match) return undefined;
      const layerIndex = Number(match[1]);
      const innerId = match[2];
      const composite = selectedPresetForPanel as any;
      const layer = composite.layers?.[layerIndex];
      const shader = layer?.shaderId ? getShaderById(layer.shaderId) : undefined;
      const def = shader?.parameters?.find((p: any) => p.id === innerId);
      const base = layer?.parameters?.[innerId];
      const v = base !== undefined ? base : def?.defaultValue;
      const num = typeof v === 'number' ? v : Number(v);
      return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
    }

    const shader = getShaderById(selectedPresetForPanel.shaderId);
    const def = shader?.parameters?.find((p: any) => p.id === paramKey);
    const base = (selectedPresetForPanel as any).parameters?.[paramKey];
    const v = base !== undefined ? base : def?.defaultValue;
    const num = typeof v === 'number' ? v : Number(v);
    return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
  }, [selectedPresetForPanel, globalParamDefs]);

  const addKeyframeForParamKey = useCallback((paramKey: string) => {
