    if (value === undefined) return;
    // Normalize the value based on parameter range before storing
    const normalized = (() => {
      if (typeof value !== 'number') return value;
      if (paramKey.startsWith('global_') || paramKey.startsWith('compositeG_')) return value; // Global params stored as absolute
      const shaderId = selectedPresetForPanel?.shaderId;
      if (!shaderId) return value;
      const shader = getShaderById(shaderId);
      const def = shader?.parameters?.find((p: any) => p.id === paramKey);
      if (!def || (def.type !== 'number' && def.type !== 'float')) return value;
      if (typeof def.min !== 'number' || typeof def.max !== 'number' || def.max <= def.min) return value;
      return Math.max(0, Math.min(1, (value - def.min) / (def.max - def.min)));
    })();
    upsertKeyframeForSelectedClip(paramKey, normalized, localT);
    setKfParamId(paramKey);
    setSelectedKeyframeTMs(localT);
  }, [selected, playheadMs, resolveKeyframeValue, upsertKeyframeForSelectedClip, selectedPresetForPanel]);

