  const setKeyframesForSelectedClipParam = useCallback((paramKey: string, frames: Array<{ tMs: number; value: any }>) => {
    if (!selected) return;
    const { track, clip } = selected;
    const nextFrames = frames
      .filter(f => f && typeof f.tMs === 'number' && isFinite(f.tMs))
      .map(f => ({ tMs: Math.max(0, Math.min(clip.durationMs, f.tMs)), value: f.value }))
      .sort((a, b) => a.tMs - b.tMs);

    setSequence(prev => {
      const nextTracks = prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
