  const applyKeyframePreset = useCallback((preset: 'rampUp' | 'rampDown' | 'easeInUp' | 'easeOutUp' | 'easeInDown' | 'easeOutDown' | 'oscillate') => {
    if (!selected) return;
    const dur = Math.max(1, selected.clip.durationMs);
    // Keyframe values are normalized (0.0-1.0), presets use 0 and 1
    const isDown = preset === 'rampDown' || preset === 'easeInDown' || preset === 'easeOutDown';
    const startValue = isDown ? 1 : 0;
    const targetValue = isDown ? 0 : 1;

    if (preset === 'oscillate') {
      const min = Math.min(startValue, targetValue);
      const max = Math.max(startValue, targetValue);
      const center = (min + max) / 2;
      const amp = (max - min) / 2;
      const cycles = 2;
      const sampleCount = 17;
      const frames: Array<{ tMs: number; value: number }> = [];
      for (let i = 0; i < sampleCount; i++) {
        const tNorm = i / (sampleCount - 1);
        const phase = (-Math.PI / 2) + tNorm * Math.PI * 2 * cycles;
        const v = center + amp * Math.sin(phase);
        frames.push({ tMs: tNorm * dur, value: v });
      }
      setKeyframesForSelectedClipParam(kfParamId, frames);
      return;
    }

    const ease = (t: number) => {
      if (preset === 'easeInUp' || preset === 'easeInDown') return t * t;
      if (preset === 'easeOutUp' || preset === 'easeOutDown') return 1 - (1 - t) * (1 - t);
      return t;
    };

    const sampleCount = preset === 'rampUp' || preset === 'rampDown' ? 2 : 5;
    const frames: Array<{ tMs: number; value: number }> = [];
    for (let i = 0; i < sampleCount; i++) {
      const tNorm = i / (sampleCount - 1);
      const tMs = tNorm * dur;
      const v = startValue + (targetValue - startValue) * ease(tNorm);
      frames.push({ tMs, value: v });
    }
    setKeyframesForSelectedClipParam(kfParamId, frames);
  }, [selected, kfParamId, resolveKeyframeValue, setKeyframesForSelectedClipParam]);

  const deleteKeyframeAtTime = (tMs: number) => {
    if (!selected) return;
    const { track, clip } = selected;
    setSequence(prev => {
      const nextTracks = prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) } as Record<string, Array<{ tMs: number; value: any }>>;
          for (const pid of Object.keys(nextKeyframes)) {
            const frames = (nextKeyframes[pid] || []).filter(f => f.tMs !== tMs);
            if (frames.length === 0) delete nextKeyframes[pid];
            else nextKeyframes[pid] = frames;
          }
          return { ...c, keyframes: nextKeyframes };
        });
        return { ...t, clips: nextClips };
      });
      return { ...prev, tracks: nextTracks };
    });
  };

  const deleteKeyframe = (paramId: string, tMs: number) => {
    if (!selected) return;
    const { track, clip } = selected;
    setSequence(prev => {
      const nextTracks = prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) };
          const frames = (nextKeyframes[paramId] || []).filter(f => f.tMs !== tMs);
          if (frames.length === 0) delete nextKeyframes[paramId];
          else nextKeyframes[paramId] = frames;
          return { ...c, keyframes: nextKeyframes };
        });
        return { ...t, clips: nextClips };
      });
      return { ...prev, tracks: nextTracks };
    });
  };

  const updateSelectedClipPreset = useCallback((apply: (preset: ShaderPreset) => ShaderPreset) => {
    if (!selectedClipId) return;
    setSequence(prev => {
      let changed = false;
      const nextTracks = prev.tracks.map(t => {
        const nextClips = t.clips.map(c => {
          if (c.id !== selectedClipId) return c;
          const base = c.preset ?? (c.presetId ? (presetsById.get(c.presetId) ?? null) : null);
          if (!base || isSequencePreset(base)) return c;
          const basePreset = clonePreset(base) as ShaderPreset;
          const nextPreset = apply(basePreset);
          changed = true;
          return { ...c, preset: nextPreset };
        });
        return t.clips === nextClips ? t : { ...t, clips: nextClips };
      });
      if (changed) setParamVersion(v => v + 1);
      return changed ? { ...prev, tracks: nextTracks } : prev;
    });
  }, [selectedClipId, presetsById]);

  const onSelectedClipParameterChange = useCallback((paramId: string, value: any) => {
    if (!selected) return;
    updateSelectedClipPreset((presetAny) => {
      if (isCompositePreset(presetAny as any) && /^composite_\d+_/.test(paramId)) {
        const match = paramId.match(/^composite_(\d+)_(.+)$/);
        if (!match) return presetAny;
        const layerIndex = Number(match[1]);
        const innerId = match[2];
        const composite = presetAny as any;
        const layers = (composite.layers || []).map((l: any, idx: number) => {
          if (idx !== layerIndex) return l;
          return { ...l, parameters: { ...(l.parameters || {}), [innerId]: value } };
        });
        return { ...composite, layers };
      }
      const preset = presetAny as any;
      return { ...preset, parameters: { ...(preset.parameters || {}), [paramId]: value } };
    });
    if (selected && (autoKeyframe || selectedKeyframeTMs != null)) {
      const localT = selectedKeyframeTMs != null ? selectedKeyframeTMs : Math.max(0, playheadMs - selected.clip.startMs);
      // Normalize for shader parameters
      const normalizedValue = (() => {
        if (typeof value !== 'number' || paramId.startsWith('global_') || paramId.startsWith('compositeG_')) return value;
        const shaderId = selectedPresetForPanel?.shaderId;
        if (!shaderId) return value;
        const shader = getShaderById(shaderId);
        const def = shader?.parameters?.find((p: any) => p.id === paramId);
        if (!def || (def.type !== 'number' && def.type !== 'float')) return value;
        if (typeof def.min !== 'number' || typeof def.max !== 'number' || def.max <= def.min) return value;
        return Math.max(0, Math.min(1, (value - def.min) / (def.max - def.min)));
      })();
      upsertKeyframeForSelectedClip(paramId, normalizedValue, localT);
      setSelectedKeyframeTMs(localT);
    }
  }, [updateSelectedClipPreset, selected, autoKeyframe, selectedKeyframeTMs, playheadMs, upsertKeyframeForSelectedClip, selectedPresetForPanel]);

  const onSelectedClipGlobalSettingChange = useCallback((settingKey: string, value: any) => {
    if (!selected) return;
    updateSelectedClipPreset((presetAny) => {
      if (isCompositePreset(presetAny as any) && /^composite_\d+_/.test(settingKey)) {
        const match = settingKey.match(/^composite_(\d+)_(.+)$/);
        if (!match) return presetAny;
        const layerIndex = Number(match[1]);
        const innerId = match[2];
        const composite = presetAny as any;
        const layers = (composite.layers || []).map((l: any, idx: number) => {
          if (idx !== layerIndex) return l;
          const nextGlobal = { ...(l.globalSettings || {}), [innerId]: value };
          const nextColors = { ...(l.colors || {}) };
          if (innerId === 'raymarchColor1') nextColors.color1 = value;
          if (innerId === 'raymarchColor2') nextColors.color2 = value;
          return { ...l, globalSettings: nextGlobal, colors: nextColors };
        });
        return { ...composite, layers };
      }
      const preset = presetAny as any;
      const nextGlobal = { ...(preset.globalSettings || {}), [settingKey]: value };
      const nextColors = { ...(preset.colors || {}) };
      if (settingKey === 'raymarchColor1') nextColors.color1 = value;
      if (settingKey === 'raymarchColor2') nextColors.color2 = value;
      return { ...preset, globalSettings: nextGlobal, colors: nextColors };
    });
    if (selected && (autoKeyframe || selectedKeyframeTMs != null)) {
      const localT = selectedKeyframeTMs != null ? selectedKeyframeTMs : Math.max(0, playheadMs - selected.clip.startMs);
      const key = /^composite_\d+_/.test(settingKey)
        ? settingKey.replace(/^composite_(\d+)_(.+)$/, 'compositeG_$1_$2')
        : `global_${settingKey}`;
      upsertKeyframeForSelectedClip(key, value, localT);
      setSelectedKeyframeTMs(localT);
    }
  }, [updateSelectedClipPreset, selected, autoKeyframe, selectedKeyframeTMs, playheadMs, upsertKeyframeForSelectedClip]);

  const onSelectedClipAnimationStatesChange = useCallback((states: any) => {
    if (!selected) return;
    updateSelectedClipPreset((presetAny) => {
      const preset = presetAny as any;
      return { ...preset, animationStates: states };
    });
  }, [updateSelectedClipPreset]);

  const onResetSelectedClipPreset = useCallback(() => {
    if (!selectedClipId) return;
    setSequence(prev => {
      let changed = false;
      const nextTracks = prev.tracks.map(t => {
        const nextClips = t.clips.map(c => {
          if (c.id !== selectedClipId) return c;
          const presetId = c.presetId ?? c.preset?.id;
          if (!presetId) return c;
          const original = presetsById.get(presetId) ?? null;
          if (!original || isSequencePreset(original)) return c;
          changed = true;
          return { ...c, preset: clonePreset(original) as ShaderPreset };
        });
        return t.clips === nextClips ? t : { ...t, clips: nextClips };
      });
      return changed ? { ...prev, tracks: nextTracks } : prev;
    });
  }, [selectedClipId, presetsById]);

  const exportSequenceAsJson = useCallback(() => {
    try {
      const exportData = {
        type: 'volumetric_sequence_preset',
        version: 1,
        name: loadedSequencePreset?.name || 'Sequence',
        sequence: clonePreset(sequence),
        outputPreset: {
          outputWidth: outputPreset.outputWidth,
          outputHeight: outputPreset.outputHeight,
          layers: outputPreset.layers,
          invertRows: outputPreset.invertRows,
          resolutionX: outputPreset.resolutionX,
          resolutionY: outputPreset.resolutionY,
          resolutionZ: outputPreset.resolutionZ,
          spoutEnabled: outputPreset.spoutEnabled,
          spoutName: outputPreset.spoutName,
          spoutWidth: outputPreset.spoutWidth,
          spoutHeight: outputPreset.spoutHeight
        }
      };
      const dataStr = JSON.stringify(exportData, null, 2);
      const blob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const safeName = (loadedSequencePreset?.name || 'Sequence').replace(/[^a-z0-9_\-\s]/gi, '_');
      a.download = `volumetric_sequence_${safeName}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error('Error exporting sequence', e);
      alert(t('sequencer.exportError', 'Error al exportar la secuencia'));
    }
  }, [sequence, loadedSequencePreset, outputPreset, t]);

  const importSequenceFromJson = useCallback(() => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json,application/json';
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0];
      if (!file) return;
      try {
        const text = await file.text();
        const data = JSON.parse(text);
        if (data && (data.type === 'volumetric_sequence_preset' || (data.sequence && data.sequence.tracks))) {
          const importedSequence = data.sequence || data;
          const next = normalizeSequence(clonePreset(importedSequence));
          const importedName = String(data.name || file.name.replace(/\.[^.]+$/, '') || t('sequencer.newSequence', 'Nueva Secuencia')).trim();
          const importedOutputPreset = data.outputPreset
            ? cloneOutputPresetSnapshot(data.outputPreset as OutputPreset)
            : cloneOutputPresetSnapshot(outputPreset);

          setSequence(next);
          setLoadedSequencePresetId(null);
          setImportedSequenceName(importedName);
          setSelectedTrackId(next.tracks[0]?.id || 't1');
          setSelectedClipId(null);
          setSelectedClipIds([]);
          setSelectedTagId(null);
          setEditingTagId(null);
          setPlay(false);
          setPlayheadImmediate(0);
          setOutputPreset(importedOutputPreset as OutputPreset);

          const preset: SequencePreset = {
            id: createId('seq'),
            name: importedName,
            shaderId: 'sequencer_timeline',
            isSequence: true,
            sequence: next,
            createdAt: Date.now(),
            updatedAt: Date.now(),
            sessionId: getCurrentSessionId(),
            outputPreset: importedOutputPreset
          };

          const saved = await PresetManager.savePreset(preset);
          if (saved) {
            await persistSavedSequenceState(preset);
            alert(t('sequencer.importSuccess', 'Secuencia importada correctamente'));
          } else {
            setSavedDocumentSignature(null);
            alert(t('sequencer.importRecovery', 'Secuencia importada. No se pudo persistir en el servidor, pero quedo guardada como borrador local de recuperacion.'));
          }
        } else {
          alert(t('sequencer.importInvalid', 'Estructura de archivo JSON inválida'));
        }
      } catch (err) {
        console.error('Error importing sequence', err);
        alert(t('sequencer.importParseError', 'Error al procesar el archivo JSON'));
      }
    };
    input.click();
  }, [outputPreset, persistSavedSequenceState, setPlayheadImmediate, setOutputPreset, t]);

  const resolveCloseRequest = useCallback((shouldClose: boolean) => {
    const resolver = closeRequestResolverRef.current;
    closeRequestResolverRef.current = null;
    closeRequestPromiseRef.current = null;
    setIsCloseConfirmSaving(false);
    setShowCloseConfirmModal(false);
    if (resolver) {
      resolver(shouldClose);
    }
  }, []);

  const handleCloseConfirmSave = useCallback(async () => {
    if (isCloseConfirmSaving) return;
    setIsCloseConfirmSaving(true);
    let saved = false;
    try {
      if (loadedSequencePresetId) {
        saved = await updateLoadedSequencePreset({ silentSuccess: true, silentError: false });
      } else {
        saved = await saveNewSequencePreset({ silentSuccess: true, silentError: false });
      }
    } catch (error) {
      console.error('Error saving sequence during close confirmation:', error);
    }
    if (!saved) {
      saved = persistRecoveryDraftNow();
    }
    if (saved) {
      resolveCloseRequest(true);
      return;
    }
    setIsCloseConfirmSaving(false);
  }, [isCloseConfirmSaving, loadedSequencePresetId, persistRecoveryDraftNow, resolveCloseRequest, saveNewSequencePreset, updateLoadedSequencePreset]);

  useEffect(() => {
    const handleBeforeUnload = (event: BeforeUnloadEvent) => {
      if ((window as any).volumetricElectron || !hasUnsavedChanges) return;
      event.preventDefault();
      event.returnValue = '';
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [hasUnsavedChanges]);

  useEffect(() => {
    const closeBridge = window as any;
    closeBridge.__volumetricHasUnsavedChanges__ = () => hasUnsavedChanges;
    closeBridge.__volumetricSaveBeforeClose__ = async () => {
      discardUnsavedOnCloseRef.current = false;
      setIsCloseConfirmSaving(false);
      setShowCloseConfirmModal(false);
      if (!hasUnsavedChanges) return true;
      try {
        let saved = false;
        if (loadedSequencePresetId) {
          saved = await updateLoadedSequencePreset({ silentSuccess: true, silentError: true });
        } else {
          saved = await saveNewSequencePreset({
            silentSuccess: true,
            silentError: true,
            promptForName: false,
            fallbackName: buildAutoSequenceName()
          });
        }

        if (!saved) {
          persistRecoveryDraftNow();
        }
      } catch (error) {
        console.error('Error in save-before-close sequencer flow:', error);
        persistRecoveryDraftNow();
      }

      // Always allow Electron to complete the close. Persistence fallback already ran above.
      return true;
    };
    closeBridge.__volumetricDiscardBeforeClose__ = async () => {
      discardUnsavedOnCloseRef.current = true;
      setIsCloseConfirmSaving(false);
      setShowCloseConfirmModal(false);
      clearRecoveryDraft();
      return true;
    };
    closeBridge.__volumetricRequestClose__ = () => {
      if (!hasUnsavedChanges) {
        return Promise.resolve(true);
      }
      if (closeRequestPromiseRef.current) {
        return closeRequestPromiseRef.current;
      }
      setIsCloseConfirmSaving(false);
      setShowCloseConfirmModal(true);
      closeRequestPromiseRef.current = new Promise<boolean>((resolve) => {
        closeRequestResolverRef.current = resolve;
      });
      return closeRequestPromiseRef.current;
    };

    return () => {
      if (closeRequestResolverRef.current) {
        closeRequestResolverRef.current(false);
        closeRequestResolverRef.current = null;
      }
      closeRequestPromiseRef.current = null;
      delete closeBridge.__volumetricHasUnsavedChanges__;
      delete closeBridge.__volumetricSaveBeforeClose__;
      delete closeBridge.__volumetricDiscardBeforeClose__;
      delete closeBridge.__volumetricRequestClose__;
    };
  }, [buildAutoSequenceName, clearRecoveryDraft, hasUnsavedChanges, loadedSequencePresetId, persistRecoveryDraftNow, saveNewSequencePreset, updateLoadedSequencePreset]);

  return (
    <div className="SequencerApp">
      <GlobalHeader
        currentPage="sequencer"
        extraActionButtons={[
          {
            title: 'Output Map Configuration',
            ariaLabel: 'Output Map Configuration',
            accent: '#00ffff',
            onClick: () => handleOpenOutputConfig(),
            icon: (
              <svg viewBox="0 0 24 24" aria-hidden="true" className="nav-btn-icon-svg">
                <path d="M14.8 5.2a4.1 4.1 0 0 0-1 4.3l-5.9 5.9a1.7 1.7 0 0 0 0 2.4l.3.3a1.7 1.7 0 0 0 2.4 0l5.9-5.9a4.1 4.1 0 0 0 4.3-1l-2.6-2.6 1.4-2.2-1.6-1.6-2.2 1.4-1-1Z" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round" />
                <path d="m9.8 16.2-2 2" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
              </svg>
            )
          },
          {
            title: showOutputMap ? 'OUTPUT MAP: ON' : 'OUTPUT MAP: OFF',
            ariaLabel: showOutputMap ? 'OUTPUT MAP: ON' : 'OUTPUT MAP: OFF',
            accent: '#00ffff',
            onClick: () => {
              setShowOutputMap(prev => {
                const next = !prev;
                setIsOutputMinimized(!next);
                return next;
              });
            },
            icon: (
              <svg viewBox="0 0 24 24" aria-hidden="true" className="nav-btn-icon-svg">
                <path d="M2.5 12s3.4-5.5 9.5-5.5 9.5 5.5 9.5 5.5-3.4 5.5-9.5 5.5S2.5 12 2.5 12Z" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
                <circle cx="12" cy="12" r="2.8" fill="none" stroke="currentColor" strokeWidth="1.8" />
              </svg>
            )
          },
          {
            title: 'Launch Output Screen',
            ariaLabel: 'Launch Output Screen',
            accent: '#00ffff',
            onClick: () => handleLaunch2D(),
            icon: (
              <svg viewBox="0 0 24 24" aria-hidden="true" className="nav-btn-icon-svg">
                <path d="M8 4H4v4M20 8V4h-4M16 20h4v-4M4 16v4h4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
                <path d="M9 9h6v6H9z" fill="none" stroke="currentColor" strokeWidth="1.5" opacity="0.75" />
              </svg>
            )
          },
          {
            title: '3D Output Preview',
            ariaLabel: '3D Output Preview',
            accent: '#5cf2c8',
            onClick: () => {
              const sessionId = getSocketSessionId();
              const url = CONFIG.getPageUrl('volumetric-output.html', {
                session: sessionId && sessionId !== '0' ? sessionId : undefined
              });
              window.open(url, '_blank', 'noopener,noreferrer');
            },
            icon: (
              <svg viewBox="0 0 24 24" aria-hidden="true" className="nav-btn-icon-svg">
                <path d="M12 3 4.5 7v10L12 21l7.5-4V7L12 3Z" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
                <path d="M4.5 7 12 11l7.5-4M12 11v10" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
              </svg>
            )
          }
        ]}
      />
      <DebugPanel
        renderMode="performance"
        performanceMode={true}
        bufferCount={bufferStats.count}
        bufferDetails={bufferStats.details}
        isMaster={isMasterClient}
        interfaceName="sequencer"
      />
      <div className="SequencerAppMain" ref={appMainRef}>
        <div
          ref={leftPanelRef}
          className={`SequencerSidebar ${isSidebarCollapsed ? 'isCollapsed' : ''} ${activePanelResizeSide === 'left' ? 'isResizing' : ''}`}
          style={isSidebarCollapsed ? undefined : {
            width: `${leftPanelWidth}px`,
            minWidth: `${leftPanelWidth}px`,
            flexBasis: `${leftPanelWidth}px`
          }}
        >
          <div className="SequencerSidebarTop">
            <button
              className="SequencerSmallButton"
              style={{ padding: '4px 8px', borderRadius: 999 }}
              onClick={() => {
                setIsSidebarCollapsed(v => {
                  const next = !v;
                  if (next) {
                    requestAnimationFrame(() => {
                      leftPanelRef.current?.scrollTo({ top: 0 });
                    });
                  }
                  return next;
                });
              }}
              type="button"
              title={isSidebarCollapsed ? t('common.expand', 'Expandir') : t('common.collapse', 'Colapsar')}
            >
              {isSidebarCollapsed ? '▶' : '◀'}
            </button>
          </div>
          {isSidebarCollapsed ? null : (
            <>
            <div className="SequencerSidebarHeader">
              <div className="SequencerCurrentSequenceName">
                {loadedSequencePreset?.name ? loadedSequencePreset.name : t('sequencer.unsavedSequence', '(sin guardar)')}
              </div>
            <div className="SequencerSidebarHeaderActions">
              <div className="SequencerSidebarPrimaryActions">
                <button
                  className="SequencerSmallButton SequencerSidebarPrimaryButton"
                  onClick={clearTimelineToEmptySeq}
                  title={t('sequencer.clearTimeline', 'Nuevo SEQ (vacío)')}
                  aria-label={t('sequencer.clearTimeline', 'Nuevo SEQ (vacío)')}
                  type="button"
                >
                  +
                </button>
                <button
                  className="SequencerSmallButton SequencerSidebarPrimaryButton"
                  onClick={() => saveNewSequencePreset()}
                  title={t('sequencer.save', 'Guardar secuencia')}
                  aria-label={t('sequencer.save', 'Guardar secuencia')}
                  type="button"
                >
                  💾
                </button>
                <button
                  className="SequencerSmallButton SequencerSidebarPrimaryButton"
                  onClick={requestUpdateSequence}
                  disabled={!loadedSequencePresetId}
                  title={t('sequencer.update', 'Actualizar')}
                  aria-label={t('sequencer.update', 'Actualizar')}
                  type="button"
                >
                  ↻
                </button>
                <button
                  className="SequencerSmallButton SequencerSidebarPrimaryButton"
                  onClick={importSequenceFromJson}
                  title={t('sequencer.importSequence', 'Importar JSON')}
                  aria-label={t('sequencer.importSequence', 'Importar JSON')}
                  type="button"
                >
                  📥
                </button>
                <button
                  className="SequencerSmallButton SequencerSidebarPrimaryButton"
                  onClick={exportSequenceAsJson}
                  title={t('sequencer.exportSequence', 'Exportar JSON')}
                  aria-label={t('sequencer.exportSequence', 'Exportar JSON')}
                  type="button"
                >
                  📤
                </button>
              </div>
              {confirmUpdateSequence && (
                <div className="SequencerInlineConfirm" role="status">
                  <span className="SequencerInlineConfirmText">¿Actualizar?</span>
                  <button className="SequencerSmallButton" type="button" onClick={confirmUpdateSequenceNow}>SI</button>
                  <button className="SequencerSmallButton" type="button" onClick={cancelUpdateSequence}>NO</button>
                </div>
              )}
            </div>
            <AdvancedLibrarySearchHeader
              items={libraryItems}
              value={librarySearch}
              onChange={setLibrarySearch}
              showKindButtonsCollapsed={false}
            />
          </div>
          <div className="SequencerSidebarBody">
            {(librarySearch.kind === 'all' || librarySearch.kind === 'sequence') && (
              <>
                <button
                  className={`SequencerSectionToggle ${librarySectionsOpen.sequences ? 'isOpen' : ''}`}
                  onClick={() => toggleLibrarySection('sequences')}
                  type="button"
                >
                  <span className="SequencerSectionToggleLabel">{t('sequencer.sequences', 'SECUENCIAS')}</span>
                  <span className="SequencerSectionToggleIcon" aria-hidden="true">{librarySectionsOpen.sequences ? '▾' : '▸'}</span>
                </button>
                {librarySectionsOpen.sequences && (
                  <div className="SequencerList">
                    {visibleSeqPresets.map((p, idx) => (
                      <div
                        key={`${p.id}:${idx}`}
                        className="SequencerItem SequencerItemSeq"
                        role="button"
                        tabIndex={0}
                        draggable
                        onClick={() => loadSequencePreset(p)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') loadSequencePreset(p);
                        }}
                        onDragStart={(e) => {
                          e.dataTransfer.setData(SEQUENCE_DND_MIME, p.id);
                          e.dataTransfer.setData('text/plain', p.id);
                          e.dataTransfer.effectAllowed = 'copy';
                        }}
                      >
                        <img className="SequencerThumb SequencerSeqThumb" src={getSequenceThumbnailSrc()} alt="" draggable={false} />
                        <div className="SequencerSeqHeader">
                          <div className="SequencerSeqName" title={p.name}>{p.name}</div>
                          <div className="SequencerBadge SequencerBadgeSeq">SEQ</div>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, padding: '0 4px', marginBottom: 2 }}>
                          <button
                            onClick={(e) => { e.stopPropagation(); handleToggleVisibility(p.id, (p as any).visibility); }}
                            type="button"
                            style={{
                              background: 'none',
                              border: '1px solid ' + ((p as any).visibility === 'private' ? '#ff6b6b88' : '#51cf6688'),
                              borderRadius: 3,
                              color: (p as any).visibility === 'private' ? '#ff6b6b' : '#51cf66',
                              cursor: 'pointer',
                              fontSize: 9,
                              padding: '1px 4px',
                              lineHeight: 1.2
                            }}
                            title={(p as any).visibility === 'private' ? 'Click to make public' : 'Click to make private'}
                          >
                            {(p as any).visibility === 'private' ? '🔒 PRIVATE' : '🌍 PUBLIC'}
                          </button>
                        </div>
                        <div className="SequencerSeqActions">
                          <button className="SequencerSmallButton" onClick={(e) => { e.stopPropagation(); addSequenceClipToSelectedTrack(p); }} type="button">
                            CLIP
                          </button>
                          <div className="SequencerSeqActionsSpacer" />
                          <button
                            className="SequencerSmallButton SequencerSeqIconButton"
                            onClick={(e) => {
                              e.stopPropagation();
                              const { outputUrl } = buildPressetViewerUrls(p.name);
                              window.open(outputUrl, '_blank', 'noopener,noreferrer');
                            }}
                            type="button"
                            title="Open Output (presset)"
                          >
                            <span className="GridInGridIcon" aria-hidden="true" />
                          </button>
                          <button
                            className="SequencerSmallButton SequencerSeqIconButton"
                            onClick={(e) => {
                              e.stopPropagation();
                              const { editorViewerUrl } = buildPressetViewerUrls(p.name);
                              window.open(editorViewerUrl, '_blank', 'noopener,noreferrer');
                            }}
                            type="button"
                            title="Open Viewer (presset)"
                          >
                            👁
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </>
            )}

            {(librarySearch.kind === 'all' || librarySearch.kind === 'effect') && (
              <>
                <button
                  className={`SequencerSectionToggle ${librarySectionsOpen.effects ? 'isOpen' : ''}`}
                  onClick={() => toggleLibrarySection('effects')}
                  type="button"
                >
                  <span className="SequencerSectionToggleLabel">EFECTOS</span>
                  <span className="SequencerSectionToggleIcon" aria-hidden="true">{librarySectionsOpen.effects ? '▾' : '▸'}</span>
                </button>
                {librarySectionsOpen.effects && (
                  <div className="SequencerList">
                    {visibleEffectPresets.map((p, idx) => (
                      <div
                        key={`${p.id}:${idx}`}
                        className="SequencerItem"
                        role="button"
                        tabIndex={0}
                        draggable
                        onClick={() => addClipToSelectedTrack(p)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') addClipToSelectedTrack(p);
                        }}
                        onDragStart={(e) => {
                          e.dataTransfer.setData(PRESET_DND_MIME, p.id);
                          e.dataTransfer.setData('text/plain', p.id);
                          e.dataTransfer.effectAllowed = 'copy';
                        }}
                      >
                        <div className="SequencerItemLeft">
                          <img className="SequencerThumb" src={getPresetThumbnailSrc(p)} alt="" draggable={false} />
                          <div className="SequencerItemText">
                          <div className="SequencerItemName" title={p.name || p.shaderId || p.id}>{p.name || p.shaderId || '(sin nombre)'}</div>
                          <div className="SequencerItemMeta">{p.shaderId}</div>
                          </div>
                          </div>
                          <div className="SequencerItemRight">
                          <div className="SequencerBadge SequencerBadgeEffect">EFECT</div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, marginTop: 2 }}>
                            <button
                              onClick={(e) => { e.stopPropagation(); handleToggleVisibility(p.id, (p as any).visibility); }}
                              type="button"
                              style={{
                                background: 'none',
                                border: '1px solid ' + ((p as any).visibility === 'private' ? '#ff6b6b88' : '#51cf6688'),
                                borderRadius: 3,
                                color: (p as any).visibility === 'private' ? '#ff6b6b' : '#51cf66',
                                cursor: 'pointer',
                                fontSize: 9,
                                padding: '1px 4px',
                                lineHeight: 1.2
                              }}
                              title={(p as any).visibility === 'private' ? 'Click to make public' : 'Click to make private'}
                            >
                              {(p as any).visibility === 'private' ? '🔒 PRIVATE' : '🌍 PUBLIC'}
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </>
            )}

            {(librarySearch.kind === 'all' || librarySearch.kind === 'preset' || librarySearch.kind === 'composite') && (
              <>
                <button
                  className={`SequencerSectionToggle ${librarySectionsOpen.presets ? 'isOpen' : ''}`}
                  onClick={() => toggleLibrarySection('presets')}
                  type="button"
                >
                  <span className="SequencerSectionToggleLabel">{t('sequencer.presets', 'PRESETS')}</span>
                  <span className="SequencerSectionToggleIcon" aria-hidden="true">{librarySectionsOpen.presets ? '▾' : '▸'}</span>
                </button>
                {librarySectionsOpen.presets && (
                  <div className="SequencerList">
                    {visibleShaderPresets.map((p, idx) => (
                      <div
                        key={`${p.id}:${idx}`}
                        className="SequencerItem"
                        role="button"
                        tabIndex={0}
                        draggable
                        onClick={() => addClipToSelectedTrack(p)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') addClipToSelectedTrack(p);
                        }}
                        onDragStart={(e) => {
                          e.dataTransfer.setData(PRESET_DND_MIME, p.id);
                          e.dataTransfer.setData('text/plain', p.id);
                          e.dataTransfer.effectAllowed = 'copy';
                        }}
                      >
                        <div className="SequencerItemLeft">
                          <img className="SequencerThumb" src={getPresetThumbnailSrc(p)} alt="" draggable={false} />
                          <div className="SequencerItemText">
                            <div className="SequencerItemName" title={p.name || p.shaderId || p.id}>{p.name || p.shaderId || '(sin nombre)'}</div>
                            <div className="SequencerItemMeta">{p.shaderId}</div>
                          </div>
                        </div>
                        <div className="SequencerItemRight">
                          <button
                            className="SequencerSmallButton"
                            onClick={(e) => {
                              e.stopPropagation();
                              const { outputUrl } = buildPressetViewerUrls(p.name);
                              window.open(outputUrl, '_blank', 'noopener,noreferrer');
                            }}
                            type="button"
                            title="Open Output (presset)"
                          >
                            <span className="GridInGridIcon" aria-hidden="true" />
                          </button>
                          <button
                            className="SequencerSmallButton"
                            onClick={(e) => {
                              e.stopPropagation();
                              const { editorViewerUrl } = buildPressetViewerUrls(p.name);
                              window.open(editorViewerUrl, '_blank', 'noopener,noreferrer');
                            }}
                            type="button"
                            title="Open Viewer (presset)"
                          >
                            👁
                          </button>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, marginTop: 1 }}>
                            <button
                              onClick={(e) => { e.stopPropagation(); handleToggleVisibility(p.id, (p as any).visibility); }}
                              type="button"
                              style={{
                                background: 'none',
                                border: '1px solid ' + ((p as any).visibility === 'private' ? '#ff6b6b88' : '#51cf6688'),
                                borderRadius: 3,
                                color: (p as any).visibility === 'private' ? '#ff6b6b' : '#51cf66',
                                cursor: 'pointer',
                                fontSize: 9,
                                padding: '1px 4px',
                                lineHeight: 1.2
                              }}
                              title={(p as any).visibility === 'private' ? 'Click to make public' : 'Click to make private'}
                            >
                              {(p as any).visibility === 'private' ? '🔒 PRIVATE' : '🌍 PUBLIC'}
                            </button>
                          </div>
                          {isCompositePreset(p) ? (
                            <div className="SequencerBadge SequencerBadgeComposite">{t('sequencer.badge.combo', 'COMBO')}</div>
                          ) : (
                            <div className="SequencerBadge SequencerBadgePreset">{t('sequencer.badge.preset', 'PRESET')}</div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </>
            )}

            {(librarySearch.kind === 'layer' || librarySearch.kind === 'all') && (
              <>
                <div className={`SequencerSectionToggle SequencerSectionToggleWithActions ${librarySectionsOpen.layers ? 'isOpen' : ''}`}>
                  <button
                    className="SequencerSectionToggleMain"
                    onClick={() => toggleLibrarySection('layers')}
                    type="button"
                  >
                    <span className="SequencerSectionToggleLabel">
                      {t('sequencer.layers', 'LAYERS')}
                      <span className="SequencerSectionToggleCount">({savedLayers.length})</span>
                    </span>
                    <span className="SequencerSectionToggleIcon" aria-hidden="true">{librarySectionsOpen.layers ? '▾' : '▸'}</span>
                  </button>
                  <div className="SequencerSectionToggleActions">
                    <button
                      className="SequencerSmallButton"
                      style={{ padding: '4px 8px' }}
                      onClick={async (e) => {
                        e.stopPropagation();
                        const layers = await LayerManager.loadLayers();
                        setSavedLayers(layers);
                      }}
                      type="button"
                    >
                      ↻
                    </button>
                    <button
                      className="SequencerSmallButton"
                      style={{ padding: '4px 8px' }}
                      onClick={async (e) => {
                        e.stopPropagation();
                        await LayerManager.importFromProjects();
                        const layers = await LayerManager.loadLayers();
                        setSavedLayers(layers);
                      }}
                      type="button"
                    >
                      IMPORT
                    </button>
                  </div>
                </div>
                {librarySectionsOpen.layers && (
                  <div className="SequencerList">
                    {visibleLayers.map((layer, idx) => (
                      <div
                        key={`${layer.id}:${idx}`}
                        className="SequencerItem"
                        role="button"
                        tabIndex={0}
                        draggable
                        onDragStart={(e) => {
                          e.dataTransfer.setData(LAYER_DND_MIME, layer.id);
                          e.dataTransfer.setData('text/plain', layer.id);
                          e.dataTransfer.effectAllowed = 'copy';
                        }}
                        onClick={() => {
                          const trackId = selectedTrackId || sequence.tracks[0]?.id;
                          if (!trackId) return;
                          const endMs = getTrackEndMs(sequence.tracks.find(t => t.id === trackId) || sequence.tracks[0]);
                          addLayerToTrack(layer, trackId, endMs);
                        }}
                        onKeyDown={(e) => {
                          if (e.key !== 'Enter' && e.key !== ' ') return;
                          const trackId = selectedTrackId || sequence.tracks[0]?.id;
                          if (!trackId) return;
                          const endMs = getTrackEndMs(sequence.tracks.find(t => t.id === trackId) || sequence.tracks[0]);
                          addLayerToTrack(layer, trackId, endMs);
                        }}
                        title={layer.sourceProject ? `${layer.name} · ${layer.sourceProject}` : layer.name}
                      >
                        <div className="SequencerItemLeft">
                          <div className="SequencerThumb" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, letterSpacing: '0.08em' }}>
                            LYR
                          </div>
                          <div className="SequencerItemText">
                            <div className="SequencerItemName" title={layer.name || layer.sourceProject || layer.id}>{layer.name || layer.sourceProject || '(sin nombre)'}</div>
                            <div className="SequencerItemMeta">{layer.presetCount} presets{layer.sourceProject ? ` · ${layer.sourceProject}` : ''}</div>
                          </div>
                        </div>
                        <div className="SequencerItemRight">
                          <button
                            className="SequencerSmallButton"
                            onClick={(e) => {
                              e.stopPropagation();
                              const { outputUrl } = buildPressetViewerUrls(layer.name);
                              window.open(outputUrl, '_blank', 'noopener,noreferrer');
                            }}
                            type="button"
                            title="Open Output (presset)"
                          >
                            <span className="GridInGridIcon" aria-hidden="true" />
                          </button>
                          <button
                            className="SequencerSmallButton"
                            onClick={(e) => {
                              e.stopPropagation();
                              const { editorViewerUrl } = buildPressetViewerUrls(layer.name);
                              window.open(editorViewerUrl, '_blank', 'noopener,noreferrer');
                            }}
                            type="button"
                            title="Open Viewer (presset)"
                          >
                            👁
                          </button>
                          <div className="SequencerBadge SequencerBadgeLayer">LAYER</div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </>
            )}
          </div>
          </>
          )}
        </div>

        {isSidebarCollapsed ? null : (
          <div
            className={`SequencerPanelResizeHandle ${activePanelResizeSide === 'left' ? 'isDragging' : ''}`}
            onPointerDown={(event) => beginSidePanelResize('left', event)}
            role="separator"
            aria-orientation="vertical"
            aria-label="Ajustar ancho del panel izquierdo"
            title="Arrastra para ajustar el ancho del panel izquierdo"
          >
            <span className="SequencerPanelResizeGrip" aria-hidden="true" />
          </div>
        )}

        <div className="SequencerContent" ref={sequencerContentRef}>
          <div className="SequencerTopBar">
            <div className="SequencerTopBarActions" />
          </div>

          <div className="SequencerPreview">
            <Canvas
              gl={{ alpha: false, preserveDrawingBuffer: true, antialias: true }}
              dpr={1}
              camera={{
                position: (() => {
                  const pos = getWorldCameraPosition(cameraPosition, cameraZoom, cameraBounds);
                  return [pos.x, pos.y, pos.z] as [number, number, number];
                })(),
                fov: 45,
                near: cameraBounds.near,
                far: cameraBounds.far
              }}
            >
              <color attach="background" args={['#000']} />
              <ambientLight intensity={0.5} />
              <pointLight position={[10, 10, 10]} intensity={1} />
              <OrbitControls
                ref={orbitControlsRef}
                enableDamping
                dampingFactor={0.08}
                minDistance={cameraBounds.minDistance}
                maxDistance={cameraBounds.maxDistance}
              />
              <CanvasFpsTracker onUpdate={setPreviewFps} />

              <VolumetricVoxelizers
                presets={activeLayersForVoxelizers}
                outputResolution={{
                  x: outputPreset.resolutionX || 64,
                  y: outputPreset.resolutionY || 64,
                  z: outputPreset.resolutionZ || 64
                }}
                onImportedTextureUpdate={upsertImportedTexture}
              />

              {showVolumetricCube && (
                <VolumetricCube
                performanceSettings={performanceSettings}
                resolutionX={outputPreset.resolutionX || 64}
                resolutionY={outputPreset.resolutionY || 64}
                resolutionZ={outputPreset.resolutionZ || 64}
                previewScaleX={previewScale.x}
                previewScaleY={previewScale.y}
                previewScaleZ={previewScale.z}
                showWireframe={visualizationParams.showWireframe}
                wireframeColor={visualizationParams.wireframeColor}
                wireframeOpacity={visualizationParams.wireframeOpacity}
                {...visualizationParams}
                {...defaults.transformParams}
                {...defaults.subdivisionParams}
                {...defaults.kaleidoParams}
                {...defaults.warpParams}
                {...defaults.onionParams}
                volumeParams={volumeParams}
                {...defaults.dissolveParams}
                {...defaults.colorParams}
                activeLayerPresets={activeLayerPresets}
                audioEnabled={!!defaults.audioParams.audioEnabled}
                bpm={Number(defaults.audioParams.bpm ?? 120)}
                audioSensitivity={Number(defaults.audioParams.audioSensitivity ?? 1)}
                particlePositions={aggregatedParticlePositions}
                particleCount={particleLayers.length > 0 ? totalParticleCount : undefined}
                particleColor={effectiveParticleColor}
                onComputeTexture={handleComputeTexture}
                noiseScale={0}
                color1="#000"
                color2="#000"
                spherePos={[0, 0, 0]}
                sphereRadius={0}
                sphereColor="#000"
                boxPos={[0, 0, 0]}
                boxSize={[0, 0, 0]}
                boxColor="#000"
                shapeBlend={0}
                generationMode="noise"
                importedTextures={importedTextures}
                viewMode={viewMode}
                onBufferStatsChange={setBufferStats}
              />
              )}

              {particleLayers.map(layer => {
                const params = layer.params || {};
                return (
                  <ParticleSystem
                    key={layer.id}
                    count={Number(params.uParticleCount ?? 200)}
                    speed={Number(params.uParticleSpeed ?? 1.0)}
                    spread={64}
                    particleSize={Number(params.uParticleSize ?? 3.0)}
                    particleColor={String(params.uParticleColor ?? effectiveParticleColor)}
                    forceX={Number(params.uParticleForceX ?? 0)}
                    forceY={Number(params.uParticleForceY ?? 0)}
                    forceZ={Number(params.uParticleForceZ ?? 0)}
                    spawnMode={Number.parseInt(String(params.uParticleSpawnMode ?? '0'))}
                    color1={(defaults.colorParams as any).raymarchColor1}
                    color2={(defaults.colorParams as any).raymarchColor2}
                    enabled={true}
                    onParticleUpdate={(positions) => handleParticleUpdate(layer.id, positions)}
                  />
                );
              })}

              <OutputCanvas
                canvasRef={outputCanvasRef}
                computeTexture={computeTexture}
                visible={showOutputMap}
                outputPreset={outputPreset}
                calibrationSettings={(remoteState as any)?.calibrationSettings ?? null}
                invertRows={outputPreset.invertRows}
                kaleidoscopeEnabled={(defaults.kaleidoParams as any).kaleidoscopeEnabled}
                kaleidoscopeSegments={(defaults.kaleidoParams as any).kaleidoscopeSegments}
                kaleidoscopeOffset={(defaults.kaleidoParams as any).kaleidoscopeOffset}
                kaleidoscopeScale={(defaults.kaleidoParams as any).kaleidoscopeScale}
                kaleidoscopeZoom={(defaults.kaleidoParams as any).kaleidoscopeZoom}
                warpEnabled={(defaults.warpParams as any).warpEnabled}
                warpFrequencyX={(defaults.warpParams as any).warpFrequencyX}
                warpFrequencyY={(defaults.warpParams as any).warpFrequencyY}
                warpFrequencyZ={(defaults.warpParams as any).warpFrequencyZ}
                warpAmplitudeX={(defaults.warpParams as any).warpAmplitudeX}
                warpAmplitudeY={(defaults.warpParams as any).warpAmplitudeY}
                warpAmplitudeZ={(defaults.warpParams as any).warpAmplitudeZ}
                warpSpeedX={(defaults.warpParams as any).warpSpeedX}
                warpSpeedY={(defaults.warpParams as any).warpSpeedY}
                warpSpeedZ={(defaults.warpParams as any).warpSpeedZ}
                warpRadialAmplitude={(defaults.warpParams as any).warpRadialAmplitude}
                warpRadialFrequency={(defaults.warpParams as any).warpRadialFrequency}
                warpRadialSpeed={(defaults.warpParams as any).warpRadialSpeed}
                onionEnabled={(defaults.onionParams as any).onionEnabled}
                onionThickness={(defaults.onionParams as any).onionThickness}
              />
            </Canvas>
            <PreviewStatsOverlay
              fps={previewFps}
              metrics={previewHardwareMetrics}
              isOpen={showPreviewStats}
              onToggle={() => setShowPreviewStats(prev => !prev)}
            />
            {/* 3D Viewport Toggle */}
            <div style={{
              position: 'absolute',
              top: 12,
              right: 12,
              zIndex: 10,
              display: 'flex',
              gap: 6,
              alignItems: 'center'
            }}>
              <button
                onClick={() => setShowVolumetricCube(prev => !prev)}
                style={{
                  background: showVolumetricCube ? 'rgba(0,200,255,0.15)' : 'rgba(255,255,255,0.05)',
                  border: `1px solid ${showVolumetricCube ? 'rgba(0,200,255,0.4)' : 'rgba(255,255,255,0.15)'}`,
                  borderRadius: '6px',
                  padding: '5px 9px',
                  cursor: 'pointer',
                  fontSize: '14px',
                  color: showVolumetricCube ? '#00ccff' : '#666',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 5,
                  opacity: 0.7,
                  transition: 'opacity 0.15s, background 0.15s'
                }}
                title={showVolumetricCube ? 'Ocultar render 3D' : 'Mostrar render 3D'}
                onMouseEnter={e => (e.currentTarget.style.opacity = '1')}
                onMouseLeave={e => (e.currentTarget.style.opacity = '0.7')}
              >
                <span>{showVolumetricCube ? '👁️' : '🚫'}</span>
                <span style={{ fontSize: 11, fontWeight: 600 }}>3D</span>
              </button>
            </div>
          </div>

          <div
            className={`SequencerTimelineResizeHandle ${isResizingTimelinePanel ? 'isDragging' : ''}`}
            onMouseDown={(e) => {
              e.preventDefault();
              timelinePanelResizeRef.current = {
                startY: e.clientY,
                startHeight: timelinePanelHeight
              };
              setIsResizingTimelinePanel(true);
            }}
            role="separator"
            aria-orientation="horizontal"
            aria-label="Ajustar altura del timeline"
            title="Arrastra para ajustar la altura del timeline"
          >
            <span className="SequencerTimelineResizeGrip" aria-hidden="true" />
          </div>

          <div
            className={`SequencerTimeline ${selectedClipIds.length ? 'hasClipSelection' : ''} ${isResizingTimelinePanel ? 'isDraggingResize' : ''}`}
            style={{ height: `${timelinePanelHeight}px` }}
          >
            <div className="SequencerTransportBar">
              <div className="SequencerTransportBarLeft">
                <button
                  className={`SequencerSmallButton SequencerTransportButton ${isPlaying ? 'isOn' : ''}`}
                  onClick={() => setPlay(!isPlaying)}
                  title={isPlaying ? t('sequencer.pause', 'Pause') : t('sequencer.play', 'Play')}
                  type="button"
                >
                  <span className="SequencerTransportButtonIcon">{isPlaying ? '⏸' : '▶'}</span>
                  <span className="SequencerTransportButtonLabel">{isPlaying ? 'PAUSE' : 'PLAY'}</span>
                </button>
                <button
                  className="SequencerSmallButton SequencerTransportButton"
                  onClick={() => { setPlay(false); setPlayhead(0); }}
                  title={t('sequencer.stop', 'Stop')}
                  type="button"
                >
                  <span className="SequencerTransportButtonIcon">⏹</span>
                  <span className="SequencerTransportButtonLabel">STOP</span>
                </button>
                <button
                  className={`SequencerSmallButton SequencerTransportButton ${loop ? 'isOn' : ''}`}
                  onClick={() => setLoop(v => !v)}
                  title={loop ? t('sequencer.loopOn', 'Loop: ON') : t('sequencer.loopOff', 'Loop: OFF')}
                  type="button"
                >
                  <span className="SequencerTransportButtonIcon">🔁</span>
                  <span className="SequencerTransportButtonLabel">LOOP</span>
                </button>
                <div className="SequencerTopBarMeta SequencerTransportBarMeta">
                  <span ref={clockRef} className="SequencerTopBarMetaCurrent">{formatClock(playheadMs)}</span>
                  <span>/</span>
                  <span className="SequencerTopBarMetaCurrent">{formatClock(timelineDurationMs)}</span>
                  <span className="SequencerTopBarMetaStatus">{isMasterClient ? 'MASTER' : 'SLAVE'}</span>
                </div>
              </div>
            </div>
            <div className="SequencerTracksShell">
              <div
                className="SequencerTracksLabels"
                onWheel={(e) => {
                  const el = tracksScrollRef.current;
                  if (!el) return;
                  el.scrollLeft += e.deltaX;
                  el.scrollTop += e.deltaY;
                  scheduleUpdateTimelineScrollState();
                }}
              >
                <div className="SequencerTrackRow SequencerTagRow">
                  <div
                    className={`SequencerTrackLabel ${selectedTagId ? 'SequencerTrackLabelSelected' : ''}`}
                    onClick={() => {
                      setSelectedClipId(null);
                      setSelectedClipIds([]);
                      setSelectedTagId(null);
                      setEditingTagId(null);
                    }}
                  >
                    <div className="SequencerTrackControls" onClick={e => e.stopPropagation()}>
                      <button
                        className="SequencerSmallButton"
                        onClick={(e) => {
                          e.stopPropagation();
                          addTagAt(playheadRef.current);
                        }}
                        title={t('sequencer.addTag', 'Agregar tag')}
                        type="button"
                      >
                        ＋
                      </button>
                      <button
                        className="SequencerSmallButton"
                        onClick={(e) => {
                          e.stopPropagation();
                          autoTagFromLayer1();
                        }}
                        title="Autotag (Layer 1)"
                        type="button"
                      >
                        ✨
                      </button>
                      <button
                        className="SequencerSmallButton"
                        onClick={(e) => {
                          e.stopPropagation();
                          addTrack();
                        }}
                        title={t('sequencer.addLayer', 'Agregar layer')}
                        type="button"
                      >
                        + layer
                      </button>
                      <button
                        className={`SequencerSmallButton ${showTagsInOutput ? 'isOn' : ''}`}
                        onClick={(e) => {
                          e.stopPropagation();
                          setShowTagsInOutput(v => !v);
                        }}
                        title={showTagsInOutput ? 'TAGS: ON' : 'TAGS: OFF'}
                        type="button"
                      >
                        TAGS
                      </button>
                    </div>
                  </div>
                </div>

                <div className="SequencerTracksLabelsInner" style={{ transform: `translateY(${-timelineScrollTopPx}px)` }}>
                  {sequence.tracks.map((track, trackIndex) => {
                    const isSelectedTrack = track.id === selectedTrackId;
                    const isTrackActive = hasSoloTracks ? track.solo : !track.muted;
                    const isTrackInactive = !isTrackActive;
                    return (
                      <div key={track.id} className={`SequencerTrackRow ${isTrackInactive ? 'isInactive' : ''} ${track.collapsed ? 'isCollapsed' : ''}`}>
                        <div
                          className={`SequencerTrackLabel ${isSelectedTrack ? 'SequencerTrackLabelSelected' : ''}`}
                          onClick={() => setSelectedTrackId(track.id)}
                        >
                          <div className="SequencerTrackName">
                            <button
                              className="SequencerCollapseButton"
                              onClick={(e) => {
                                e.stopPropagation();
                                setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, collapsed: !t.collapsed } : t) }));
                              }}
                              title={track.collapsed ? 'Expand layer' : 'Collapse layer'}
                              type="button"
                            >
                              {track.collapsed ? '▸' : '▾'}
                            </button>
                            {track.collapsed ? (
                              <div className="SequencerTrackNameText">{track.name}</div>
                            ) : (
                              <input
                                value={track.name}
                                onChange={e => {
                                  const value = e.target.value;
                                  setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, name: value } : t) }));
                                }}
                              />
                            )}
                          </div>
                          <div className="SequencerTrackControls" onClick={e => e.stopPropagation()}>
                            {!track.collapsed && sequence.tracks.length > 1 && (
                              <>
                                <button
                                  className="SequencerSmallButton"
                                  disabled={trackIndex === 0}
                                  onClick={e => {
                                    e.stopPropagation();
                                    moveTrack(track.id, -1);
                                  }}
                                  title="Subir layer"
                                  type="button"
                                >
                                  ▲
                                </button>
                                <button
                                  className="SequencerSmallButton"
                                  disabled={trackIndex === sequence.tracks.length - 1}
                                  onClick={e => {
                                    e.stopPropagation();
                                    moveTrack(track.id, 1);
                                  }}
                                  title="Bajar layer"
                                  type="button"
                                >
                                  ▼
                                </button>
                              </>
                            )}
                            <button
                              className={`SequencerSmallButton ${track.muted ? 'isOn' : ''}`}
                              onClick={e => {
                                e.stopPropagation();
                                setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, muted: !t.muted } : t) }));
                              }}
                            >
                              M
                            </button>
                            <button
                              className={`SequencerSmallButton ${track.solo ? 'isOn' : ''}`}
                              onClick={e => {
                                e.stopPropagation();
                                setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, solo: !t.solo } : t) }));
                              }}
                            >
                              S
                            </button>
                            {!track.collapsed && sequence.tracks.length > 1 && (
                              <button
                                className="SequencerSmallButton"
                                onClick={e => {
                                  e.stopPropagation();
                                  removeTrack(track.id);
                                }}
                                title={t('common.delete', 'Eliminar')}
                              >
                                ×
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div
                className="SequencerTracksScroll"
                ref={tracksScrollRef}
                onScroll={scheduleUpdateTimelineScrollState}
              >
                <div className="SequencerTrackRow SequencerTagRow">
                  <div
                    className="SequencerTrackLane SequencerTagLane"
                    style={{ width: effectiveLaneWidthPx }}
                    onDoubleClick={(e) => {
                      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const raw = laneXToTimeMs(x, pixelsPerSecondRef.current);
                      addTagAt(clamp(raw, 0, Math.max(0, timelineDurationMs)));
                    }}
                    onMouseDown={(e) => {
                      if (e.button !== 0) return;
                      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const next = clamp(laneXToTimeMs(x, pixelsPerSecondRef.current), 0, Math.max(0, timelineDurationMs));
                      setPlayhead(next);
                    }}
                  >
                    <div className="SequencerPlayhead" style={{ left: `${timeToLaneX(playheadMs, pixelsPerSecond)}px` }} />
                    {(() => {
                      const segs = getTagSegments(sequence);
                      return segs.map((seg, idx) => {
                        const tag = seg.tag;
                        const x = timeToLaneX(seg.startMs, pixelsPerSecond);
                        const width = Math.max(24, ((seg.endMs - seg.startMs) / 1000) * pixelsPerSecond);
                        const isSelected = selectedTagId === tag.id;
                        const isEditing = editingTagId === tag.id;
                        const isActive = playheadMs >= seg.startMs && playheadMs < seg.endMs;
                        const minStartMs = idx > 0 ? (segs[idx - 1]?.startMs ?? 0) + 1 : 0;
                        const maxEndMs = idx < segs.length - 1 ? (segs[idx + 1]?.startMs ?? seg.endMs) : Number.POSITIVE_INFINITY;
                        return (
                          <div
                            key={tag.id}
                            className={`SequencerTagSegment ${isSelected ? 'isSelected' : ''} ${isActive ? 'isActive' : ''}`}
                            style={{ left: `${x}px`, width: `${width}px` }}
                            onMouseDown={(e) => {
                              e.stopPropagation();
                              if (e.button !== 0) return;
                              setSelectedClipId(null);
                              setSelectedClipIds([]);
                              setSelectedTagId(tag.id);
                              setEditingTagId(null);
                              dragTagRef.current = { tagId: tag.id, startMs: tag.tMs, startX: e.clientX };
                              setIsDraggingTag(true);
                            }}
                            onDoubleClick={(e) => {
                              e.stopPropagation();
                              setSelectedClipId(null);
                              setSelectedClipIds([]);
                              setSelectedTagId(tag.id);
                              setEditingTagId(tag.id);
                            }}
                            title={tag.label || 'TAG'}
                          >
                            <div
                              className="SequencerTagResizeHandle SequencerTagResizeHandleStart"
                              onMouseDown={(e) => {
                                e.stopPropagation();
                                if (e.button !== 0) return;
                                setSelectedClipId(null);
                                setSelectedClipIds([]);
                                setSelectedTagId(tag.id);
                                setEditingTagId(null);
                                resizeTagRef.current = { tagId: tag.id, startMs: seg.startMs, endMs: seg.endMs, startX: e.clientX, edge: 'start', minStartMs, maxEndMs };
                                setIsResizingTag(true);
                              }}
                            />
                            <div className="SequencerTagDot" />
                            {isEditing ? (
                              <input
                                className="SequencerTagInput"
                                value={tag.label}
                                onChange={(e) => updateTagLabel(tag.id, e.target.value)}
                                onBlur={() => setEditingTagId(null)}
                                onKeyDown={(e) => {
                                  if (e.key === 'Enter' || e.key === 'Escape') {
                                    (e.currentTarget as HTMLInputElement).blur();
                                  }
                                }}
                                autoFocus
                              />
                            ) : (
                              <div className="SequencerTagText">{tag.label || 'TAG'}</div>
                            )}
                            <div
                              className="SequencerTagResizeHandle SequencerTagResizeHandleEnd"
                              onMouseDown={(e) => {
                                e.stopPropagation();
                                if (e.button !== 0) return;
                                setSelectedClipId(null);
                                setSelectedClipIds([]);
                                setSelectedTagId(tag.id);
                                setEditingTagId(null);
                                resizeTagRef.current = { tagId: tag.id, startMs: seg.startMs, endMs: seg.endMs, startX: e.clientX, edge: 'end', minStartMs, maxEndMs };
                                setIsResizingTag(true);
                              }}
                            />
                          </div>
                        );
                      });
                    })()}
                  </div>
                </div>
                {sequence.tracks.map((track) => {
                  const isTrackActive = hasSoloTracks ? track.solo : !track.muted;
                  const isTrackInactive = !isTrackActive;
                  const laneWidthPx2 = effectiveLaneWidthPx;
                  const playheadX = timeToLaneX(playheadMs, pixelsPerSecond);
                  return (
                    <div key={track.id} className={`SequencerTrackRow ${isTrackInactive ? 'isInactive' : ''} ${track.collapsed ? 'isCollapsed' : ''}`}>
                      <div
                        className="SequencerTrackLane"
                        style={{ width: laneWidthPx2 }}
                        ref={(el) => {
                          if (el) trackLaneRefs.current.set(track.id, el);
                          else trackLaneRefs.current.delete(track.id);
                        }}
                        onDragOver={(e) => {
                          e.preventDefault();
                          e.dataTransfer.dropEffect = 'copy';
                          setSelectedTrackId(track.id);
                        }}
                        onDrop={(e) => {
                          e.preventDefault();
                          const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                          const x = e.clientX - rect.left;
                          const startMs = Math.max(0, laneXToTimeMs(x, pixelsPerSecondRef.current));

                          setSelectedTrackId(track.id);

                          const layerId = e.dataTransfer.getData(LAYER_DND_MIME);
                          if (layerId) {
                            const layer = savedLayers.find(l => l.id === layerId);
                            if (layer) addLayerToTrack(layer, track.id, startMs);
                            return;
                          }

                          const presetId = e.dataTransfer.getData(PRESET_DND_MIME) || e.dataTransfer.getData(SEQUENCE_DND_MIME) || e.dataTransfer.getData('text/plain');
                          if (!presetId) return;
                          const presetAny = presetsById.get(presetId);
                          if (!presetAny) return;
                          addPresetOrSequenceClipToTrackAt(track.id, presetAny, startMs);
                        }}
                        onMouseDown={e => {
                          if (e.button !== 0) return;
                          const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                          const x = e.clientX - rect.left;
                          const clicked = clamp(laneXToTimeMs(x, pixelsPerSecondRef.current), 0, Math.max(0, timelineDurationMs));
                          setSelectedTrackId(track.id);
                          setSelectedClipId(null);
                          setSelectedClipIds([]);
                          setSelectedTagId(null);
                          setEditingTagId(null);

                          const clips = (track.clips || []).slice().sort((a, b) => a.startMs - b.startMs);
                          let prevEnd = 0;
                          for (const c of clips) {
                            const end = c.startMs + Math.max(1, c.durationMs);
                            if (end <= clicked && end >= prevEnd) prevEnd = end;
                          }
                          let nextStart: number | null = null;
                          for (const c of clips) {
                            if (c.startMs > clicked) {
                              nextStart = c.startMs;
                              break;
                            }
                          }
                          const nextPlayhead = nextStart != null && clicked > prevEnd && clicked < nextStart ? prevEnd : clicked;
                          setPlayheadImmediate(nextPlayhead);

                          scrubRef.current = {
                            trackId: track.id,
                            startX: e.clientX,
                            startTime: performance.now(),
                            rectLeft: rect.left,
                            started: false
                          };
                          setIsScrubbingTimeline(true);
                        }}
                      >
                        <div className="SequencerPlayhead" style={{ left: `${playheadX}px` }} />
                        {(() => {
                          const sortedClips = (track.clips || []).slice().sort((a, b) => a.startMs - b.startMs);
                          const vr = visibleTimelineRange;
                          const visibleClips = sortedClips.filter(clip => {
                            const clipEndMs = clip.startMs + Math.max(1, clip.durationMs);
                            return clipEndMs >= vr.startMs && clip.startMs <= vr.endMs;
                          });
                          return visibleClips.map((clip) => {
                            const left = Math.round(timeToLaneX(clip.startMs, pixelsPerSecond));
                            const width = Math.max(16, Math.round((clip.durationMs / 1000) * pixelsPerSecond));
                            const isSelected = selectedClipIdsSet.has(clip.id);
                            const presetName = clip.preset?.name || (clip.presetId ? presetsById.get(clip.presetId)?.name : '') || 'Clip';
                            const presetThumb = clip.preset && !isSequencePreset(clip.preset) ? getPresetThumbnailSrc(clip.preset) : undefined;
                            const kfDataForTimeline = (() => {
                              if (!clip.keyframes) return [];
                              const paramIds = Object.keys(clip.keyframes);
                              return paramIds.map(paramId => {
                                const frames = (clip.keyframes![paramId] || [])
                                  .filter((f: any) => f && typeof f.tMs === 'number' && isFinite(f.tMs) && typeof f.value === 'number' && isFinite(f.value))
                                  .slice()
                                  .sort((a: any, b: any) => a.tMs - b.tMs) as Array<{ tMs: number; value: number }>;
                                if (!frames.length) return null;
                                // Global param keyframes (global_ / compositeG_) store raw values (e.g. BPM=120)
                                // Shader param keyframes store normalized values (0.0-1.0)
                                const isGlobal = paramId.startsWith('global_') || paramId.startsWith('compositeG_');
                                const values = frames.map(f => f.value);
                                const minV = isGlobal ? Math.min(...values) : 0;
                                const maxV = isGlobal ? Math.max(...values) : 1;
                                const span = Math.max(1e-6, maxV - minV);
                                const color = paramLevelColors[paramId] || getKeyframeColorByIndex(paramIds.indexOf(paramId));
                                paramLevelColors[paramId] = color;
                                return { paramId, frames, minV, maxV, span, color };
                              }).filter(Boolean) as Array<{ paramId: string; frames: Array<{ tMs: number; value: number }>; minV: number; maxV: number; span: number; color: string }>;
                            })();
                            const hasAnyKF = kfDataForTimeline.some(d => d.frames.length > 0);
                            return (
                              <div
                                key={clip.id}
                                className={`SequencerClip ${isSelected ? 'SequencerClipSelected' : ''}`}
                                style={{ left, width }}
                                onMouseDown={e => {
                                  e.stopPropagation();
                                  if (e.button !== 0) return;
                                  setSelectedTagId(null);
                                  setEditingTagId(null);
                                  setSelectedTrackId(track.id);
                                  if (e.shiftKey || e.ctrlKey || e.metaKey) {
                                    setSelectedClipIds(prev => {
                                      const has = prev.includes(clip.id);
                                      const next = (e.ctrlKey || e.metaKey)
                                        ? (has ? prev.filter(id => id !== clip.id) : [...prev, clip.id])
                                        : (has ? prev : [...prev, clip.id]);
                                      const primary = next.length ? next[next.length - 1] : null;
                                      setSelectedClipId(primary);
                                      return next;
                                    });
                                  } else {
                                    setSelectedClipId(clip.id);
                                    setSelectedClipIds([clip.id]);
                                  }
                                  dragClipRef.current = { clipId: clip.id, startMs: clip.startMs, startX: e.clientX };
                                  setIsDraggingClip(true);
                                }}
                                title={presetName}
                              >
                                <div
                                  className="SequencerClipHandle SequencerClipHandleStart"
                                  onMouseDown={(e) => {
                                    e.stopPropagation();
                                    if (e.button !== 0) return;
                                    setSelectedClipId(clip.id);
                                    setSelectedClipIds([clip.id]);
                                    setSelectedTrackId(track.id);
                                    resizeClipRef.current = { trackId: track.id, clipId: clip.id, startMs: clip.startMs, durationMs: clip.durationMs, startX: e.clientX, edge: 'start' };
                                    setIsResizingClip(true);
                                  }}
                                />
                                {presetThumb && !track.collapsed && <img className="SequencerClipThumb" src={presetThumb} alt="" draggable={false} />}
                                {presetName}
                                {hasAnyKF && (
                                  <div className="SequencerClipKeyframes">
                                    {kfDataForTimeline.map(kfData => (
                                      <svg key={kfData.paramId} className="SequencerClipKeyframesSvg" viewBox="0 0 1000 1000" preserveAspectRatio="none">
                                        {kfData.frames.length >= 2 && (
                                          <path
                                            d={kfData.frames.map((f, idx) => {
                                              const x = (clamp(f.tMs, 0, clip.durationMs) / Math.max(1, clip.durationMs)) * 1000;
                                              const y = 1000 - ((f.value - kfData.minV) / kfData.span) * 1000;
                                              return `${idx === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${clamp(y, 0, 1000).toFixed(2)}`;
                                            }).join(' ')}
                                            fill="none"
                                            stroke={kfData.color}
                                            strokeWidth="20"
                                            strokeLinecap="round"
                                            strokeLinejoin="round"
                                          />
                                        )}
                                      </svg>
                                    ))}
                                    {kfDataForTimeline.map(kfData =>
                                      kfData.frames.map((f) => {
                                        const tLocal = clamp(f.tMs, 0, clip.durationMs);
                                        const xPct = (tLocal / Math.max(1, clip.durationMs)) * 100;
                                        const yPct = (1 - ((f.value - kfData.minV) / kfData.span)) * 100;
                                        const isActive = selectedKeyframeTMs != null && Math.abs(selectedKeyframeTMs - tLocal) <= 6;
                                        return (
                                          <div
                                            key={`${kfData.paramId}:${f.tMs}`}
                                            className={`SequencerClipKeyframe ${isActive ? 'isActive' : ''}`}
                                            style={{
                                              left: `${clamp(xPct, 0, 100)}%`,
                                              top: `${clamp(yPct, 0, 100)}%`,
                                              borderColor: isActive ? 'rgba(255,255,255,0.95)' : kfData.color,
                                              background: kfData.color,
                                              opacity: 0.85
                                            }}
                                            title={`${kfData.paramId} @ ${formatClock(tLocal)}\n${f.value.toFixed(3)}`}
                                            onPointerDown={(e) => {
                                              e.stopPropagation();
                                              if (e.button !== 0) return;
                                              setSelectedClipId(clip.id);
                                              setSelectedClipIds([clip.id]);
                                              setSelectedTrackId(track.id);
                                              setSelectedKeyframeTMs(tLocal);
                                              setPlayhead(clip.startMs + tLocal);
                                              const dotEl = e.currentTarget as HTMLElement;
                                              const clipRect = dotEl.closest('.SequencerClip')?.getBoundingClientRect();
                                              if (!clipRect) return;
                                              const kfSpan = kfData.span;
                                              const kfMinV = kfData.minV;
                                              const doc = e.currentTarget.ownerDocument;
                                              const onMove = (ev: PointerEvent) => {
                                                ev.preventDefault();
                                                const relX = ev.clientX - clipRect.left;
                                                const newTMs = (relX / Math.max(1, clipRect.width)) * clip.durationMs;
                                                const clampedTMs = clamp(newTMs, 0, clip.durationMs);
                                                const relY = ev.clientY - clipRect.top;
                                                const newNormY = 1 - (relY / Math.max(1, clipRect.height));
                                                const newValue = kfMinV + newNormY * kfSpan;
                                                const clampedValue = clamp(newValue, kfMinV, kfMinV + kfSpan);
                                                moveKeyframeForSelectedClip(kfData.paramId, tLocal, clampedTMs, clampedValue);
                                                setSelectedKeyframeTMs(clampedTMs);
                                                setPlayhead(clip.startMs + clampedTMs);
                                              };
                                              const onUp = () => {
                                                doc.removeEventListener('pointermove', onMove);
                                                doc.removeEventListener('pointerup', onUp);
                                              };
                                              doc.addEventListener('pointermove', onMove);
                                              doc.addEventListener('pointerup', onUp);
                                            }}
                                          />
                                        );
                                      })
                                    )}
                                  </div>
                                )}
                                <div
                                  className="SequencerClipHandle SequencerClipHandleEnd"
                                  onMouseDown={(e) => {
                                    e.stopPropagation();
                                    if (e.button !== 0) return;
                                    setSelectedClipId(clip.id);
                                    setSelectedClipIds([clip.id]);
                                    setSelectedTrackId(track.id);
                                    resizeClipRef.current = { trackId: track.id, clipId: clip.id, startMs: clip.startMs, durationMs: clip.durationMs, startX: e.clientX, edge: 'end' };
                                    setIsResizingClip(true);
                                  }}
                                />
                              </div>
                            );
                          });
                        })()}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="SequencerTimeBar">
              <div className="SequencerTimeBarLeft">
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <div className="SequencerTagLabel">TIME</div>
                  <button
                    className="SequencerSmallButton"
                    onClick={() => zoomTimelineTo(pixelsPerSecond / 1.15)}
                    type="button"
                    title="Zoom out"
                  >
                    −
                  </button>
                  <button
                    className="SequencerSmallButton"
                    onClick={() => zoomTimelineTo(pixelsPerSecond * 1.15)}
                    type="button"
                    title="Zoom in"
                  >
                    +
                  </button>
                </div>
              </div>
              <div className="SequencerTimeBarRight">
                <div
                  className="SequencerZoomLayer"
                  ref={timelineScrollbarRef}
                >
                  <div
                    className="SequencerTimelineScrollbarWindow"
                    style={{ left: `${timelineScrollbarThumbLeftPx}px`, width: `${timelineScrollbarThumbWidthPx}px` }}
                    onMouseDown={(e) => beginTimelineScrollbarDrag('move', e)}
                  >
                    <div
                      className="SequencerTimelineScrollbarHandle SequencerTimelineScrollbarHandleStart"
                      onMouseDown={(e) => beginTimelineScrollbarDrag('resizeStart', e)}
                    />
                    <div
                      className="SequencerTimelineScrollbarHandle SequencerTimelineScrollbarHandleEnd"
                      onMouseDown={(e) => beginTimelineScrollbarDrag('resizeEnd', e)}
                    />
                  </div>
                </div>

                <div
                  className="SequencerTimeBarTrack"
                  onDragOver={(e) => {
                    const hasPreset = e.dataTransfer.types.includes(PRESET_DND_MIME) || e.dataTransfer.types.includes(SEQUENCE_DND_MIME) || e.dataTransfer.types.includes('text/plain');
                    const hasLayer = e.dataTransfer.types.includes(LAYER_DND_MIME);
                    if (!hasPreset && !hasLayer) return;
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'copy';
                  }}
                  onDrop={(e) => {
                    e.preventDefault();
                    const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                    const x = e.clientX - rect.left;
                    const raw = laneXToTimeMs(Math.max(0, x) + timelineScrollLeftPx, pixelsPerSecondRef.current);
                    const startMs = Math.max(0, raw);

                    const trackId = sequence.tracks.find(t => t.id === selectedTrackId)?.id || sequence.tracks[0]?.id;
                    if (!trackId) return;
                    setSelectedTrackId(trackId);

                    const layerId = e.dataTransfer.getData(LAYER_DND_MIME);
                    if (layerId) {
                      const layer = savedLayers.find(l => l.id === layerId);
                      if (layer) addLayerToTrack(layer, trackId, startMs);
                      return;
                    }

                    const presetId = e.dataTransfer.getData(PRESET_DND_MIME) || e.dataTransfer.getData(SEQUENCE_DND_MIME) || e.dataTransfer.getData('text/plain');
                    if (!presetId) return;
                    const presetAny = presetsById.get(presetId);
                    if (!presetAny) return;
                    addPresetOrSequenceClipToTrackAt(trackId, presetAny, startMs);
                  }}
                >
                  <div
                    className="SequencerTimeBarViewport"
                    onMouseDown={(e) => {
                      if (e.button !== 0) return;
                      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const tMs = laneXToTimeMs(Math.max(0, x) + timelineScrollLeftPx, pixelsPerSecondRef.current);
                      const next = clamp(tMs, 0, Math.max(0, timelineDurationMs));
                      setPlayhead(next);

                      // Enable drag-to-scrub on timebar (reuses existing scrubRef infrastructure)
                      scrubRef.current = {
                        trackId: '',
                        startX: e.clientX,
                        startTime: performance.now(),
                        rectLeft: rect.left,
                        started: false
                      };
                      setIsScrubbingTimeline(true);
                    }}
                  >
                    <div ref={playheadDotRef} className="SequencerTimeBarPlayhead" style={{ left: `${timeToLaneX(playheadMs, pixelsPerSecond) - timelineScrollLeftPx}px` }} />
                    <div
                      className="SequencerTimeBarContent"
                      style={{ width: effectiveLaneWidthPx, transform: `translateX(${-timelineScrollLeftPx}px)` }}
                    >
                      {rulerMarks.filter(m => {
                        return m.xPx >= visibleTimelineRange.startPx && m.xPx <= visibleTimelineRange.endPx;
                      }).map(m => (
                        <div key={m.tMs} className={`SequencerRulerTick ${m.isMajor ? 'isMajor' : 'isMinor'}`} style={{ left: `${m.xPx}px` }}>
                          <div className="SequencerRulerLine" />
                          {m.label ? <div className="SequencerRulerText">{m.label}</div> : null}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <OutputCanvasDisplay
            ref={outputCanvasRef}
            visible={showOutputMap}
            outputPreset={outputPreset}
            onOutputPresetChange={setOutputPreset}
            isMinimized={isOutputMinimized}
            broadcastUpdate={broadcastUpdate as any}
            showConfigButton={false}
            openConfigSignal={outputConfigOpenSignal}
          />
        </div>

        {isMobileLayout && !isMobileInspectorOpen ? (
          <button
            className="SequencerMobileInspectorToggle"
            type="button"
            onClick={() => setIsMobileInspectorOpen(true)}
            title="Abrir inspector"
            aria-label="Abrir inspector"
          >
            INSPECTOR
          </button>
        ) : null}

        {isMobileLayout && isMobileInspectorOpen ? (
          <button
            className="SequencerMobileInspectorBackdrop"
            type="button"
            onClick={() => setIsMobileInspectorOpen(false)}
            aria-label="Cerrar inspector"
          />
        ) : null}

        {!isMobileLayout && !isInspectorCollapsed ? (
          <div
            className={`SequencerPanelResizeHandle ${activePanelResizeSide === 'right' ? 'isDragging' : ''}`}
            onPointerDown={(event) => beginSidePanelResize('right', event)}
            role="separator"
            aria-orientation="vertical"
            aria-label="Ajustar ancho del panel derecho"
            title="Arrastra para ajustar el ancho del panel derecho"
          >
            <span className="SequencerPanelResizeGrip" aria-hidden="true" />
          </div>
        ) : null}

        <div
          ref={rightPanelRef}
          className={`SequencerRightPanel ${isDesktopInspectorCollapsed ? 'isCollapsed' : ''} ${activePanelResizeSide === 'right' ? 'isResizing' : ''} ${isMobileLayout ? 'isMobileOverlay' : ''} ${isMobileInspectorOpen ? 'isMobileOpen' : ''}`}
          style={!isMobileLayout && !isInspectorCollapsed ? {
            width: `${rightPanelWidth}px`,
            minWidth: `${rightPanelWidth}px`,
            flexBasis: `${rightPanelWidth}px`
          } : undefined}
        >
          <div className="SequencerInspectorTop">
            <button
              className="SequencerSmallButton"
              style={{ padding: '4px 8px', borderRadius: 999 }}
              onClick={() => {
                if (isMobileLayout) {
                  setIsMobileInspectorOpen(false);
                  return;
                }
                setIsInspectorCollapsed(v => {
                  const next = !v;
                  if (next) {
                    requestAnimationFrame(() => {
                      rightPanelRef.current?.scrollTo({ top: 0 });
                    });
                  }
                  return next;
                });
              }}
              type="button"
              title={isMobileLayout ? t('common.close', 'Cerrar') : isInspectorCollapsed ? t('common.expand', 'Expandir') : t('common.collapse', 'Colapsar')}
            >
              {isMobileLayout ? '✕' : isInspectorCollapsed ? '◀' : '▶'}
            </button>
          </div>
          {isInspectorVisible ? (
            <>
              {!selected && (
                <div style={{ fontSize: 12, opacity: 0.8 }}>
                  {t('sequencer.selectClipHint', 'Seleccioná un clip para editarlo.')}
                </div>
              )}

              <div className="SequencerInspectorTabs">
                <button
                  className={`SequencerInspectorTab ${inspectorTab === 'layer' ? 'isActive' : ''}`}
                  onClick={() => setInspectorTab('layer')}
                  type="button"
                >
                  Layers
                </button>
                <button
                  className={`SequencerInspectorTab ${inspectorTab === 'params' ? 'isActive' : ''}`}
                  onClick={() => setInspectorTab('params')}
                  type="button"
                >
                  Params
                </button>
                <button
                  className={`SequencerInspectorTab ${inspectorTab === 'clip' ? 'isActive' : ''}`}
                  onClick={() => setInspectorTab('clip')}
                  type="button"
                >
                  Seq
                </button>
                <button
                  className={`SequencerInspectorTab ${inspectorTab === 'viz' ? 'isActive' : ''}`}
                  onClick={() => setInspectorTab('viz')}
                  type="button"
                >
                  Viz
                </button>
                <button
                  className={`SequencerInspectorTab ${inspectorTab === 'history' ? 'isActive' : ''}`}
                  onClick={() => setInspectorTab('history')}
                  type="button"
                >
                  History
                </button>
              </div>

              {inspectorTab === 'layer' && (
                <div className="SequencerInspectorSectionBody">
                  {(() => {
                    const track = sequence.tracks.find(tk => tk.id === selectedTrackId);
                    const enabled = (track?.layerColorsEnabled ?? !!(track?.colors?.color1 || track?.colors?.color2 || track?.colorSettings)) === true;
                    return (
                      <>
                        <div className="SequencerFieldRow" style={{ gap: 8 }}>
                          <button
                            className={`SequencerSmallButton ${enabled ? 'isOn' : ''}`}
                            onClick={toggleSelectedTrackColors}
                            type="button"
                          >
                            LAYER COLORS
                          </button>
                        </div>

                        {enabled ? (
                          <>
                            <ColorPicker
                              id={`seq_track_${selectedTrackId}_color1`}
                              label="Color 1"
                              value={track?.colors?.color1 ?? '#ffffff'}
                              onChange={(c) => setSelectedTrackColor('color1', c)}
                              disabled={false}
                              showPresets={true}
                              compact={true}
                            />
                            <ColorPicker
                              id={`seq_track_${selectedTrackId}_color2`}
                              label="Color 2"
                              value={track?.colors?.color2 ?? '#000000'}
                              onChange={(c) => setSelectedTrackColor('color2', c)}
                              disabled={false}
                              showPresets={true}
                              compact={true}
                            />

                            <div className="SequencerFieldRow">
                              <label>Color Pattern</label>
                              <select
                                value={track?.colorSettings?.colorPattern ?? 'linear'}
                                onChange={(e) => setSelectedTrackColorSetting('colorPattern', e.target.value)}
                              >
                                <option value="linear">linear</option>
                                <option value="vertical">vertical</option>
                                <option value="radial">radial</option>
                                <option value="angular">angular</option>
                                <option value="depth">depth</option>
                                <option value="fbm">fbm</option>
                                <option value="random">random</option>
                              </select>
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Color Type</label>
                              <select
                                value={track?.colorSettings?.colorType ?? '2_colors'}
                                onChange={(e) => setSelectedTrackColorSetting('colorType', e.target.value)}
                              >
                                <option value="2_colors">2_colors</option>
                                <option value="rainbow">rainbow</option>
                              </select>
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Color Frequency</label>
                              <input
                                type="range"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorFrequency ?? 1.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorFrequency', Number(e.target.value))}
                                style={{ flex: 1 }}
                              />
                              <input
                                type="number"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorFrequency ?? 1.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorFrequency', Number(e.target.value))}
                                className="slider-value-number"
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Color Speed</label>
                              <input
                                type="range"
                                min={-10}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorSpeed ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorSpeed', Number(e.target.value))}
                                style={{ flex: 1 }}
                              />
                              <input
                                type="number"
                                min={-10}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorSpeed ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorSpeed', Number(e.target.value))}
                                className="slider-value-number"
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Color Offset</label>
                              <input
                                type="range"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorOffset ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorOffset', Number(e.target.value))}
                                style={{ flex: 1 }}
                              />
                              <input
                                type="number"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorOffset ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorOffset', Number(e.target.value))}
                                className="slider-value-number"
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Flip X</label>
                              <input
                                type="checkbox"
                                checked={!!track?.colorSettings?.colorFlipX}
                                onChange={(e) => setSelectedTrackColorSetting('colorFlipX', e.target.checked)}
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Flip Y</label>
                              <input
                                type="checkbox"
                                checked={!!track?.colorSettings?.colorFlipY}
                                onChange={(e) => setSelectedTrackColorSetting('colorFlipY', e.target.checked)}
                              />
                            </div>
                          </>
                        ) : (
                          <div style={{ fontSize: 12, opacity: 0.7 }}>
                            Activá LAYER COLORS para elegir colores del layer.
                          </div>
                        )}
                      </>
                    );
                  })()}

                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.layerName', 'Layer')}</label>
                    <input
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.name ?? ''}
                      onChange={(e) => {
                        const value = e.target.value;
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, name: value } : t) }));
                      }}
                    />
                  </div>
                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.brightness', 'Brillo')}</label>
                    <input
                      type="range"
                      min={0}
                      max={2}
                      step={0.01}
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.brightness ?? 1}
                      onChange={e => {
                        const value = Number(e.target.value);
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, brightness: value } : t) }));
                      }}
                      style={{ flex: 1 }}
                    />
                    <input
                      type="number"
                      min={0}
                      max={2}
                      step={0.01}
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.brightness ?? 1}
                      onChange={e => {
                        const value = Number(e.target.value);
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, brightness: value } : t) }));
                      }}
                      className="slider-value-number"
                    />
                  </div>
                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.blend', 'Blend')}</label>
                    <select
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.blendMode ?? 1}
                      onChange={(e) => {
                        const value = Number(e.target.value);
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, blendMode: value } : t) }));
                      }}
                    >
                      {BLEND_MODE_OPTIONS.map(opt => (
                        <option key={opt.value} value={opt.value}>{opt.label}</option>
                      ))}
                    </select>
                  </div>

                  {selected && (
                    <>
                      <div className="SequencerFieldRow">
                        <label>{t('sequencer.start', 'Inicio')}</label>
                        <input
                          type="number"
                          value={selected.clip.startMs}
                          onChange={e => {
                            const value = Number(e.target.value);
                            setSequence(prev => ({
                              ...prev,
                              tracks: prev.tracks.map(t => t.id !== selected.track.id ? t : ({
                                ...t,
                                clips: sortTrackOnly({
                                  ...t,
                                  clips: t.clips.map(c => c.id !== selected.clip.id ? c : ({ ...c, startMs: Math.max(0, value) }))
                                }).clips
                              }))
                            }));
                          }}
                        />
                      </div>

                      <div className="SequencerFieldRow">
                        <label>{selectedClipIds.length > 1 ? `${t('sequencer.duration', 'Duración')} (x${selectedClipIds.length})` : t('sequencer.duration', 'Duración')}</label>
                        <input
                          type="text"
                          value={durationTextClipId === selected.clip.id ? durationText : formatClockMs(selected.clip.durationMs)}
                          onChange={e => {
                            setDurationText(e.target.value);
                            setDurationTextClipId(selected.clip.id);
                          }}
                          onBlur={() => {
                            const parsed = parseTimecodeToMs(durationText);
                            if (parsed == null) {
                              setDurationText(formatClockMs(selected.clip.durationMs));
                              setDurationTextClipId(selected.clip.id);
                              return;
                            }
                            const value = Math.max(1, parsed);
                            const ids = selectedClipIds.length ? selectedClipIds : [selected.clip.id];
                            const idsSet = new Set(ids);
                            setSequence(prev => ({
                              ...prev,
                              tracks: prev.tracks.map(t => {
                                if (!(t.clips || []).some(c => idsSet.has(c.id))) return t;
                                return {
                                  ...t,
                                  clips: sortTrackOnly({
                                    ...t,
                                    clips: t.clips.map(c => idsSet.has(c.id) ? ({ ...c, durationMs: value }) : c)
                                  }).clips
                                };
                              })
                            }));
                            setDurationText(formatClockMs(value));
                            setDurationTextClipId(selected.clip.id);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              (e.currentTarget as HTMLInputElement).blur();
                              return;
                            }
                            if (e.key === 'Escape') {
                              setDurationText(formatClockMs(selected.clip.durationMs));
                              setDurationTextClipId(selected.clip.id);
                              (e.currentTarget as HTMLInputElement).blur();
                            }
                          }}
                        />
                      </div>

                      <div className="SequencerFieldRow" style={{ gap: 6 }}>
                        <button className="SequencerSmallButton" onClick={() => setPlayhead(selected.clip.startMs)} type="button">
                          {t('sequencer.goStart', 'Ir al inicio')}
                        </button>
                        <button className="SequencerSmallButton" onClick={() => setPlayhead(selected.clip.startMs + selected.clip.durationMs)} type="button">
                          {t('sequencer.goEnd', 'Ir al final')}
                        </button>
                        <button className="SequencerSmallButton" onClick={removeSelectedClip} type="button">
                          {t('common.delete', 'Eliminar')}
                        </button>
                      </div>
                    </>
                  )}
                </div>
              )}

              {inspectorTab === 'params' && (
                <div className="SequencerInspectorSectionBody">
                  {/* Sub-tabs: KEYFRAMES | VALUES */}
                  <div className="ParamsSubTabs" style={{ display: 'flex', gap: 4, marginBottom: 8, borderBottom: '1px solid rgba(255,255,255,0.1)', paddingBottom: 6 }}>
                    <button
                      className={`SequencerSmallButton ${paramsSubTab === 'keyframes' ? 'isOn' : ''}`}
                      onClick={() => setParamsSubTab('keyframes')}
                      type="button"
                      style={{ flex: 1, fontSize: 10, textTransform: 'uppercase', letterSpacing: '0.5px' }}
                    >
                      KEYFRAMES
                    </button>
                    <button
                      className={`SequencerSmallButton ${paramsSubTab === 'values' ? 'isOn' : ''}`}
                      onClick={() => setParamsSubTab('values')}
                      type="button"
                      style={{ flex: 1, fontSize: 10, textTransform: 'uppercase', letterSpacing: '0.5px' }}
                    >
                      VALUES
                    </button>
                  </div>

                  {paramsSubTab === 'keyframes' ? (
                    <>
                      {!selected ? (
                        <div style={{ fontSize: 12, opacity: 0.75, marginTop: 10 }}>
                          {t('sequencer.selectClipHint', 'Seleccioná un clip para editarlo.')}
                        </div>
                      ) : (
                        <div className="SequencerKeyframesSection">
                          <div className="SequencerKeyframesGraph">
                            {(() => {
                              const frames = (selected.clip.keyframes?.[kfParamId] || []).slice().sort((a, b) => a.tMs - b.tMs);
                              const dur = Math.max(1, selected.clip.durationMs);
                              const w = 360;
                              const h = 84;
                              const padX = 10;
                              const padY = 10;
                              const usableW = w - padX * 2;
                              const usableH = h - padY * 2;
                              const canEdit = typeof resolveKeyframeValue(kfParamId) === 'number';
                              const getRangeFromParamDef = () => {
                                if (!selectedPresetForPanel) return null as null | { min: number; max: number };
                                if (kfParamId.startsWith('global_')) {
                                  const id = kfParamId.slice('global_'.length);
                                  const def = globalParamDefs.find(p => p.id === id);
                                  if (!def || def.type !== 'number') return null;
                                  if (typeof def.min !== 'number' || typeof def.max !== 'number' || !isFinite(def.min) || !isFinite(def.max) || def.max <= def.min) return null;
                                  return { min: def.min, max: def.max };
                                }
                                if (kfParamId.startsWith('compositeG_')) {
                                  const match = kfParamId.match(/^compositeG_(\d+)_(.+)$/);
                                  if (!match) return null;
                                  const id = match[2];
                                  const def = globalParamDefs.find(p => p.id === id);
                                  if (!def || def.type !== 'number') return null;
                                  if (typeof def.min !== 'number' || typeof def.max !== 'number' || !isFinite(def.min) || !isFinite(def.max) || def.max <= def.min) return null;
                                  return { min: def.min, max: def.max };
                                }
                                if (isCompositePreset(selectedPresetForPanel as any) && /^composite_\d+_/.test(kfParamId)) {
                                  const match = kfParamId.match(/^composite_(\d+)_(.+)$/);
                                  if (!match) return null;
                                  const layerIndex = Number(match[1]);
                                  const innerId = match[2];
                                  const composite = selectedPresetForPanel as any;
                                  const layer = composite.layers?.[layerIndex];
                                  const shader = layer?.shaderId ? getShaderById(layer.shaderId) : undefined;
                                  const def = shader?.parameters?.find((p: any) => p.id === innerId);
                                  if (!def || (def.type !== 'number' && def.type !== 'float')) return null;
                                  if (typeof def.min !== 'number' || typeof def.max !== 'number' || !isFinite(def.min) || !isFinite(def.max) || def.max <= def.min) return null;
                                  return { min: def.min, max: def.max };
                                }
                                const shader = getShaderById(selectedPresetForPanel.shaderId);
                                const def = shader?.parameters?.find((p: any) => p.id === kfParamId);
                                if (!def || (def.type !== 'number' && def.type !== 'float')) return null;
                                if (typeof def.min !== 'number' || typeof def.max !== 'number' || !isFinite(def.min) || !isFinite(def.max) || def.max <= def.min) return null;
                                return { min: def.min, max: def.max };
                              };

                              const values = frames.map(f => (typeof f.value === 'number' ? f.value : NaN)).filter(v => isFinite(v));
                              const valuesMin = values.length ? Math.min(...values) : 0;
                              const valuesMax = values.length ? Math.max(...values) : 1;
                              const defRange = canEdit ? getRangeFromParamDef() : null;
                              // Global param keyframes (global_ / compositeG_) store raw values (e.g. BPM=120, not normalized)
                              // Shader param keyframes store normalized values (0.0-1.0)
                              const isGlobalKf = kfParamId.startsWith('global_') || kfParamId.startsWith('compositeG_');

                              const graphMin = defRange
                                ? (isGlobalKf ? defRange.min : 0)
                                : (valuesMin - (Math.abs(valuesMax - valuesMin) < 1e-6 ? Math.max(1, Math.abs(valuesMin) * 0.25) : (valuesMax - valuesMin) * 0.2));
                              const graphMax = defRange
                                ? (isGlobalKf ? defRange.max : 1)
                                : (valuesMax + (Math.abs(valuesMax - valuesMin) < 1e-6 ? Math.max(1, Math.abs(valuesMin) * 0.25) : (valuesMax - valuesMin) * 0.2));
                              const span = Math.max(1e-6, graphMax - graphMin);

                              const kfColor = getKeyframeColor(kfParamId, keyframeCandidates);

                              const yOf = (v: any) => {
                                if (typeof v !== 'number' || !isFinite(v)) return padY + usableH / 2;
                                const tNorm = (v - graphMin) / span;
                                return padY + (1 - tNorm) * usableH;
                              };
                              const xOf = (tMs: number) => padX + (clamp(tMs, 0, dur) / dur) * usableW;
                              const playX = xOf(Math.max(0, playheadMs - selected.clip.startMs));
                              const d = frames.map((f, idx) => `${idx === 0 ? 'M' : 'L'} ${xOf(f.tMs).toFixed(2)} ${yOf(f.value).toFixed(2)}`).join(' ');

                              return (
                                <svg
                                  width="100%"
                                  viewBox={`0 0 ${w} ${h}`}
                                  onDoubleClick={(e) => {
                                    if (!canEdit) return;
                                    const rect = (e.currentTarget as SVGSVGElement).getBoundingClientRect();
                                    const xSvg = ((e.clientX - rect.left) / Math.max(1, rect.width)) * w;
                                    const ySvg = ((e.clientY - rect.top) / Math.max(1, rect.height)) * h;
                                    const tLocal = clamp(((xSvg - padX) / Math.max(1e-6, usableW)) * dur, 0, dur);
                                    const vRaw = graphMin + (1 - ((ySvg - padY) / Math.max(1e-6, usableH))) * span;
                                    const v = clamp(vRaw, graphMin, graphMax);
                                    upsertKeyframeForSelectedClip(kfParamId, v, tLocal);
                                    setSelectedKeyframeTMs(tLocal);
                                    setPlayhead(selected.clip.startMs + tLocal);
                                  }}
                                  onPointerMove={(e) => {
                                    if (!canEdit) return;
                                    if (!keyframeDragRef.current || keyframeDragRef.current.paramId !== kfParamId) return;
                                    const rect = (e.currentTarget as SVGSVGElement).getBoundingClientRect();
                                    const xSvg = ((e.clientX - rect.left) / Math.max(1, rect.width)) * w;
                                    const ySvg = ((e.clientY - rect.top) / Math.max(1, rect.height)) * h;
                                    const tLocal = clamp(((xSvg - padX) / Math.max(1e-6, usableW)) * dur, 0, dur);
                                    const vRaw = graphMin + (1 - ((ySvg - padY) / Math.max(1e-6, usableH))) * span;
                                    const v = clamp(vRaw, graphMin, graphMax);
                                    moveKeyframeForSelectedClip(kfParamId, keyframeDragRef.current.tMs, tLocal, v);
                                    keyframeDragRef.current = { paramId: kfParamId, tMs: tLocal };
                                    setSelectedKeyframeTMs(tLocal);
                                    setPlayhead(selected.clip.startMs + tLocal);
                                  }}
                                  onPointerUp={(e) => {
                                    if (!keyframeDragRef.current) return;
                                    try {
                                      (e.currentTarget as SVGSVGElement).releasePointerCapture(e.pointerId);
                                    } catch { }
                                    keyframeDragRef.current = null;
                                  }}
                                  onPointerLeave={() => {
                                    keyframeDragRef.current = null;
                                  }}
                                >
                                  <rect x="0" y="0" width={w} height={h} rx="10" fill="rgba(0,0,0,0.25)" stroke="rgba(255,255,255,0.08)" />
                                  <line x1={playX} y1={6} x2={playX} y2={h - 6} stroke="rgba(255,0,128,0.9)" strokeWidth="2" />
                                  {frames.length >= 2 && (
                                    <path d={d} fill="none" stroke={kfColor} strokeWidth="2" />
                                  )}
                                  {frames.map((f) => (
                                    <circle
                                      key={f.tMs}
                                      cx={xOf(f.tMs)}
                                      cy={yOf(f.value)}
                                      r={selectedKeyframeTMs != null && Math.abs(selectedKeyframeTMs - f.tMs) <= 6 ? 6 : 4}
                                      fill={selectedKeyframeTMs != null && Math.abs(selectedKeyframeTMs - f.tMs) <= 6 ? kfColor : kfColor}
                                      fillOpacity={selectedKeyframeTMs != null && Math.abs(selectedKeyframeTMs - f.tMs) <= 6 ? 1 : 0.7}
                                      onPointerDown={(e) => {
                                        e.stopPropagation();
                                        if (!canEdit) return;
                                        if ((e as any).button !== 0) return;
                                        const tLocal = clamp(f.tMs, 0, selected.clip.durationMs);
                                        keyframeDragRef.current = { paramId: kfParamId, tMs: tLocal };
                                        setSelectedKeyframeTMs(tLocal);
                                        setPlayhead(selected.clip.startMs + tLocal);
                                        const svg = (e.currentTarget as SVGCircleElement).ownerSVGElement;
                                        if (svg) {
                                          try {
                                            svg.setPointerCapture(e.pointerId);
                                          } catch { }
                                        }
                                      }}
                                      style={{ cursor: 'grab' }}
                                    />
                                  ))}
                                </svg>
                              );
                            })()}
                          </div>

                          <div className="SequencerKeyframesToolbar">
                            <button className="SequencerSmallButton" onClick={addKeyframeToSelectedClip} type="button">
                              {t('sequencer.addKeyframe', 'Agregar')} @ {formatClock(Math.max(0, playheadMs - selected.clip.startMs))}
                            </button>
                            <button className="SequencerSmallButton" onClick={() => clearKeyframesForParamKey(kfParamId)} type="button">
                              {t('sequencer.clearKeyframes', 'Borrar KF')}
                            </button>
                          </div>

                          <div className="SequencerFieldRow">
                            <label>{t('sequencer.param', 'Parámetro')}</label>
                            {keyframeCandidates.length > 0 ? (
                              <select
                                className="SequencerSelect"
                                value={kfParamId}
                                onChange={(e) => setKfParamId(e.target.value)}
                              >
                                {keyframeCandidates.map(p => (
                                  <option key={p.id} value={p.id}>{p.label}</option>
                                ))}
                              </select>
                            ) : (
                              <input value={kfParamId} onChange={e => setKfParamId(e.target.value)} />
                            )}
                          </div>

                          <div className="SequencerKeyframeAnimRow">
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('rampUp')}
                              type="button"
                              title="Linear ramp up"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><line x1="2" y1="12" x2="12" y2="2" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>ramp</span>
                            </button>
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('rampDown')}
                              type="button"
                              title="Linear ramp down"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><line x1="2" y1="2" x2="12" y2="12" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>ramp↓</span>
                            </button>
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('easeInUp')}
                              type="button"
                              title="Ease in (slow start, fast end) up"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><path d="M2 12 C4 12 6 10 8 7 C10 4 11 3 12 2" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>ease in</span>
                            </button>
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('easeOutUp')}
                              type="button"
                              title="Ease out (fast start, slow end) up"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><path d="M2 12 C4 12 6 11 8 9 C10 7 11 4 12 2" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>ease out</span>
                            </button>
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('easeInDown')}
                              type="button"
                              title="Ease in (slow start, fast end) down"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><path d="M2 2 C4 2 6 4 8 7 C10 10 11 11 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>ease in↓</span>
                            </button>
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('easeOutDown')}
                              type="button"
                              title="Ease out (fast start, slow end) down"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><path d="M2 2 C4 2 6 3 8 5 C10 7 11 10 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>ease out↓</span>
                            </button>
                            <button
                              className="SequencerKeyframeAnimButton"
                              disabled={typeof resolveKeyframeValue(kfParamId) !== 'number'}
                              onClick={() => applyKeyframePreset('oscillate')}
                              type="button"
                              title="Oscillating wave"
                            >
                              <svg width="14" height="14" viewBox="0 0 14 14" style={{verticalAlign:'middle',marginRight:2}}><path d="M2 7 C4 2 6 12 8 7 C10 2 12 12 13 7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
                              <span style={{fontSize:9,opacity:0.8}}>wave</span>
                            </button>
                          </div>

                          {keyframeCandidates.length > 0 && (
                            <div className="SequencerKeyframesParamList">
                              {keyframeCandidates.map(p => {
                                const isActive = kfParamId === p.id;
                                return (
                                  <div key={p.id} className="SequencerKeyframesParamRow">
                                    <button
                                      className="SequencerSmallButton"
                                      onClick={() => addKeyframeForParamKey(p.id)}
                                      type="button"
                                      title="Agregar keyframe"
                                    >
                                      ＋
                                    </button>
                                    <button
                                      className={`SequencerKeyframesParamButton ${isActive ? 'isActive' : ''}`}
                                      onClick={() => setKfParamId(p.id)}
                                      type="button"
                                      title={p.id}
                                    >
                                      {p.label}
                                    </button>
                                  </div>
                                );
                              })}
                            </div>
                          )}
                        </div>
                      )}
                    </>
                  ) : (
                    <DynamicParameterPanel
                      selectedPreset={selectedPresetForPanel}
                      onParameterChange={onSelectedClipParameterChange}
                      onGlobalSettingChange={onSelectedClipGlobalSettingChange}
                      animationStates={selectedPresetForPanel?.animationStates}
                      onAnimationStatesChange={onSelectedClipAnimationStatesChange}
                      onResetPreset={onResetSelectedClipPreset}
                    />
                  )}
                </div>
              )}

                {inspectorTab === 'clip' && (
                <div className="SequencerInspectorSectionBody">
                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.totalDuration', 'Duración total')}</label>
                    <input
                      className="SequencerDurationInput"
                      value={timelineDurationDraft}
                      onChange={(e) => setTimelineDurationDraft(e.target.value)}
                      onFocus={(e) => e.currentTarget.select()}
                      onBlur={() => commitTimelineDurationDraft(timelineDurationDraft)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.currentTarget.blur();
                          return;
                        }
                        if (e.key === 'Escape') {
                          setTimelineDurationDraft(formatClock(timelineDurationMs));
                          e.currentTarget.blur();
                        }
                      }}
                      title="Duración total (hh:mm:ss.ms o milisegundos)"
                    />
                  </div>
                </div>
              )}

              {inspectorTab === 'viz' && (
                <div className="SequencerInspectorSectionBody">
                  <CustomControlsPanel3
                    title="🔓 Access"
                    controls={accessControls as any}
                    onChange={(id, value) => handleAccessConfigChange(id as any, !!value)}
                    collapsible={false}
                  />
                  {(() => {
                    const sessionId = getSocketSessionId();
                    const origin = window.location.origin;
                    const outputUrl = new URL(CONFIG.getPageUrl('output.html', { session: sessionId }), origin).toString();
                    const editorUrl = new URL(CONFIG.getPageUrl('volumetric-output.html', { session: sessionId }), origin).toString();
                    const canOutput = accessConfig.output;
                    const canEditor = accessConfig.volumetricOutput;
                    const verifyColor = accessVerify.status === 'ok'
                      ? 'rgba(0,255,170,0.85)'
                      : accessVerify.status === 'mismatch'
                        ? 'rgba(255,170,0,0.9)'
                        : accessVerify.status === 'error'
                          ? 'rgba(255,80,120,0.9)'
                          : 'rgba(255,255,255,0.75)';
                    return (
                      <div style={{ marginTop: 10, paddingTop: 10, borderTop: '1px solid rgba(255,255,255,0.08)' }}>
                        <div style={{ fontSize: 12, opacity: 0.85, marginBottom: 6 }}>
                          API: {CONFIG.API_URL}
                        </div>
                        <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8 }}>
                          <button className="SequencerSmallButton" onClick={() => void verifyAccessAgainstServer()} type="button">VERIFICAR</button>
                          <div style={{ fontSize: 12, color: verifyColor, flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {accessVerify.message}
                          </div>
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                            <div style={{ fontSize: 12, opacity: 0.85 }}>Output público ({canOutput ? 'ON' : 'OFF'})</div>
                            <input
                              value={outputUrl}
                              readOnly
                              onFocus={(e) => e.currentTarget.select()}
                              style={{ width: '100%', fontSize: 12, padding: '6px 8px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.12)', background: 'rgba(0,0,0,0.25)', color: 'rgba(255,255,255,0.9)' }}
                            />
                          </div>
                          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                            <div style={{ fontSize: 12, opacity: 0.85 }}>Editor público (hideview) ({canEditor ? 'ON' : 'OFF'})</div>
                            <input
                              value={editorUrl}
                              readOnly
                              onFocus={(e) => e.currentTarget.select()}
                              style={{ width: '100%', fontSize: 12, padding: '6px 8px', borderRadius: 8, border: '1px solid rgba(255,255,255,0.12)', background: 'rgba(0,0,0,0.25)', color: 'rgba(255,255,255,0.9)' }}
                            />
                          </div>
                        </div>
                      </div>
                    );
                  })()}

                  <div style={{ height: 12 }} />

                  <div className="SequencerControlsSidebarEmbedded">
                    <ControlsSidebar3
                      embedded
                      showVolumetricCube={showVolumetricCube}
                      onShowVolumetricCubeChange={setShowVolumetricCube}
                      onResetView={onResetView}
                      visualizationParams={visualizationParams}
                      onVisualizationChange={onVisualizationChange}
                      onVisualizationReset={onVisualizationReset}
                      cameraPosition={cameraPosition}
                      cameraZoom={cameraZoom}
                      cameraZoomMin={cameraBounds.minZoom}
                      cameraZoomMax={cameraBounds.maxZoom}
                      onCameraRotationChange={onCameraRotationChange}
                      onCameraZoomChange={onCameraZoomChange}
                      performanceSettings={performanceSettings}
                      onPerformanceSettingsChange={setPerformanceSettings}
                      onCameraSave={onCameraSave}
                      onCameraResetSaved={onCameraResetSaved}
                      onCameraResetStandard={onCameraResetStandard}
                      autoRotateYaw={autoRotateYaw}
                      autoRotatePitch={autoRotatePitch}
                      onAutoRotateYawChange={setAutoRotateYaw}
                      onAutoRotatePitchChange={setAutoRotatePitch}
                      viewMode={viewMode}
                      onViewModeChange={setViewMode}
                      volumeParams={volumeParams}
                      onVolumeChange={onVolumeChange}
                      onVolumeReset={onVolumeReset}
                    />
                  </div>
                </div>
              )}

              {inspectorTab === 'history' && (
                <div className="SequencerInspectorSectionBody">
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginBottom: 8 }}>
                    <div style={{ fontSize: 12, opacity: 0.85 }}>
                      Historial (Ctrl+Z)
                    </div>
                    <div style={{ fontSize: 12, opacity: 0.6 }}>
                      {undoHistory.length} / {HISTORY_LIMIT}
                    </div>
                  </div>
                  {undoHistory.length === 0 ? (
                    <div style={{ fontSize: 12, opacity: 0.7 }}>
                      Vacío
                    </div>
                  ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                      {undoHistory.slice().reverse().map(h => (
                        <div
                          key={h.id}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            gap: 10,
                            padding: '6px 8px',
                            borderRadius: 8,
                            border: '1px solid rgba(255,255,255,0.08)',
                            background: 'rgba(0,0,0,0.22)'
                          }}
                        >
                          <div style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 12 }}>
                            {h.label}
                          </div>
                          <button
                            className="SequencerSmallButton"
                            type="button"
                            onClick={() => {
                              const entries = undoHistoryRef.current;
                              const idx = entries.findIndex(e => e.id === h.id);
                              if (idx < 0) return;
                              const nextEntries = entries.slice(0, idx);
                              undoHistoryRef.current = nextEntries;
                              setUndoHistory(nextEntries);
                              if (pendingUndoCommitTimerRef.current != null) {
                                window.clearTimeout(pendingUndoCommitTimerRef.current);
                                pendingUndoCommitTimerRef.current = null;
                              }
                              pendingUndoSnapshotRef.current = null;
                              isUndoingRef.current = true;
                              const restored = clonePreset(entries[idx].sequence) as TimelineSequence;
                              setSequence(restored);
                              setSelectedClipId(null);
                              setSelectedClipIds([]);
                              setSelectedTagId(null);
                              setEditingTagId(null);
                              setSelectedTrackId(prev => (restored.tracks.some(t => t.id === prev) ? prev : (restored.tracks[0]?.id || 't1')));
                            }}
                            title="Volver a este punto"
                          >
                            UNDO
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </>
          ) : null}
        </div>
      </div>

      {showCloseConfirmModal && (
        <div className="SequencerCloseModalOverlay" role="presentation">
          <div className="SequencerCloseModal" role="dialog" aria-modal="true" aria-labelledby="sequencer-close-title">
            <div className="SequencerCloseModalHeader">
              <div id="sequencer-close-title" className="SequencerCloseModalTitle">
                Cambios sin guardar
              </div>
            </div>
            <div className="SequencerCloseModalBody">
              <div className="SequencerCloseModalMessage">
                Hay cambios pendientes en los presets del sequencer.
              </div>
              <div className="SequencerCloseModalDetail">
                Desea guardar los cambios antes de cerrar Volumetric Suite?
              </div>
            </div>
            <div className="SequencerCloseModalActions">
              <button
                className="SequencerSmallButton isOn"
                onClick={handleCloseConfirmSave}
                disabled={isCloseConfirmSaving}
                type="button"
              >
                {isCloseConfirmSaving ? 'Guardando...' : 'Guardar y cerrar'}
              </button>
              <button
                className="SequencerSmallButton"
                onClick={() => resolveCloseRequest(true)}
                disabled={isCloseConfirmSaving}
                type="button"
              >
                Cerrar sin guardar
              </button>
              <button
                className="SequencerSmallButton"
                onClick={() => resolveCloseRequest(false)}
                disabled={isCloseConfirmSaving}
                type="button"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {showDisplaySelector && (
        <div style={{
          position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
          background: 'rgba(0,0,0,0.85)', zIndex: 999999, display: 'flex',
          alignItems: 'center', justifyContent: 'center', backdropFilter: 'blur(4px)'
        }}>
          <div style={{
            background: '#1a1a1a', border: '1px solid #00ffff', borderRadius: 8,
            padding: 24, width: 320, boxShadow: '0 8px 32px rgba(0,0,0,0.5)'
          }}>
            <h3 style={{ margin: '0 0 16px 0', color: '#00ffff', textAlign: 'center', fontSize: 16 }}>Select Monitor</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {availableDisplays.map(d => (
                <button
                  key={d.id}
                  onClick={() => {
                    (window as any).volumetricElectron?.openOutputFullscreen(d.id);
                    setShowDisplaySelector(false);
                  }}
                  style={{
                    padding: '12px', background: '#2a2a2a', border: '1px solid #444',
                    borderRadius: 6, color: '#fff', cursor: 'pointer', fontSize: 14,
                    transition: 'all 0.2s', textAlign: 'left',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center'
                  }}
                  onMouseEnter={e => e.currentTarget.style.borderColor = '#00ffff'}
                  onMouseLeave={e => e.currentTarget.style.borderColor = '#444'}
                >
                  <span>{d.label}</span>
                  {d.isPrimary && <span style={{ fontSize: 10, background: '#00ffff', color: '#000', padding: '2px 6px', borderRadius: 4 }}>Primary</span>}
                </button>
              ))}
              <button
                onClick={() => setShowDisplaySelector(false)}
                style={{
                  padding: '10px', background: 'transparent', border: '1px solid #666',
                  borderRadius: 6, color: '#ccc', cursor: 'pointer', marginTop: 8, fontSize: 13
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
